package trip.net

import kotlin.js.Promise

/** Asks for the saved demo files once and hands the same promise to every caller, until a round fails. */
class SavedDemoLoader(private val fetchText: (path: String) -> Promise<String>) {
    private var kept: Promise<SavedDemoData>? = null

    /** Returns the saved demo, asking for the files only when no round is kept or the kept round has failed. */
    fun load(): Promise<SavedDemoData> {
        kept?.let { return it }
        val demo = fetchSavedDemo(fetchText)
        kept = demo
        // The catch only forgets this round if it is still the kept one; the original promise is returned so callers see the rejection.
        demo.catch { if (kept === demo) kept = null }
        return demo
    }
}
