package trip.plan

import trip.Family
import trip.match.FamilyMatch
import trip.match.Match
import trip.place.Place
import kotlin.math.ceil

/**
 * A suggested stop: the place, its seconds from the start on the route, its detour in whole minutes, and its match.
 * [Match.percent] already includes the detour (see [percentAfterDetour]), and the match names that deduction.
 */
data class Stop(val place: Place, val routeSeconds: Int, val detourMinutes: Int, val match: Match)

/** Suggests stops along a route at about the family's drive intervals. Deterministic. */
object StopPlanner {
    private const val END_MARGIN_SECONDS = 600

    /**
     * Targets come every max drive, while at least ten minutes remain. Each target takes the best place whose route
     * time is in the quarter drive before it, up to the target. If there is none, it takes the best place in the later
     * half of the drive after the last stop, so no gap between stops goes over a drive. A stop moves the next target to
     * its time plus a drive. Only places that pass [filter] are candidates.
     */
    fun plan(
        route: Route,
        places: List<Place>,
        family: Family,
        maxDetourMinutes: Int = 15,
        filter: StopFilter = StopFilter(),
    ): List<Stop> {
        val driveSeconds = family.maxDriveMinutes * 60
        val candidates = candidates(route, places, family, filter).filter { it.detourMinutes <= maxDetourMinutes }
        val stops = mutableListOf<Stop>()
        var target = driveSeconds
        var last = 0
        while (target <= route.totalSeconds - END_MARGIN_SECONDS) {
            val earliest = target - driveSeconds / 4
            val best = candidates.filter { it.routeSeconds in earliest..target }.minWithOrNull(BEST_FIRST)
                ?: candidates.filter { it.routeSeconds in last + driveSeconds / 2..minOf(target, last + driveSeconds) }
                    .minWithOrNull(BEST_FIRST)
            if (best == null) {
                target += driveSeconds
            } else {
                stops += best
                last = best.routeSeconds
                target = best.routeSeconds + driveSeconds
            }
        }
        return stops
    }
}

/**
 * The places that are close enough to the route to be a stop, with their route time, detour and match. Places whose
 * detour is over [maxDetourMinutes] are left out, as in [StopPlanner.plan].
 */
fun nearNow(
    route: Route,
    atSeconds: Int,
    places: List<Place>,
    family: Family,
    withinMinutes: Int = 15,
    limit: Int = 3,
    filter: StopFilter = StopFilter(),
    maxDetourMinutes: Int = 15,
): List<Stop> = candidates(route, places, family, filter)
    .filter { it.detourMinutes <= maxDetourMinutes }
    .filter { it.routeSeconds in atSeconds..atSeconds + withinMinutes * 60 }
    .sortedWith(BEST_FIRST)
    .take(limit)

private const val METRES_PER_MINUTE_AT_50_KMH = 50_000.0 / 60.0

private fun candidates(route: Route, places: List<Place>, family: Family, filter: StopFilter): List<Stop> = places.map { place ->
    val (index, distance) = route.nearest(place.lat, place.lon)
    val detour = ceil(2 * distance / METRES_PER_MINUTE_AT_50_KMH).toInt()
    val base = FamilyMatch.score(place, family)
    val shown = percentAfterDetour(base.percent, detour)
    val points = base.percent - shown
    Stop(
        place = place,
        routeSeconds = route.points[index].seconds,
        detourMinutes = detour,
        match = if (points == 0) base else base.copy(percent = shown, detourPoints = points, detourMinutes = detour),
    )
}.filter { filter.accepts(it) }

/** Highest shown percent first; then the smaller detour, a named place, the earlier route time, and the smaller osmId. */
private val BEST_FIRST: Comparator<Stop> = compareBy<Stop> { -it.match.percent }
    .thenBy { it.detourMinutes }
    .thenBy { if (it.place.name == null) 1 else 0 }
    .thenBy { it.routeSeconds }
    .thenBy { it.place.osmId }
