package trip.plan

import kotlin.math.roundToInt

// The map layers of the route and the part of it searched so far, for the map while a plan is made.

/** The map layer of the whole route, drawn muted. */
const val ROUTE_LAYER = "route"

/** The map layer of the part of the route searched so far, drawn over [ROUTE_LAYER]. */
const val PROGRESS_LAYER = "progress"

/** The map layers in the order they are added: the later one is drawn on top. */
fun routeLayerOrder(): List<String> = listOf(ROUTE_LAYER, PROGRESS_LAYER)

/**
 * The points of [route] from its start up to [share] of the way along it, counted in points as the place queries are
 * cut. A share of 0 gives the first point and 1 gives all of them; a share outside 0 to 1 is taken as the nearer end.
 */
fun routeUpTo(route: Route, share: Double): List<RoutePoint> {
    val last = (share.coerceIn(0.0, 1.0) * route.points.lastIndex).roundToInt()
    return route.points.subList(0, last + 1)
}
