package trip.plan

/** Detour minutes that cost nothing; each minute above this takes one point off the shown match percent. */
const val FREE_DETOUR_MINUTES = 5

/**
 * The match percent shown for a place [detourMinutes] off the route: [percent] minus one point per minute above
 * [FREE_DETOUR_MINUTES], never below 0.
 */
fun percentAfterDetour(percent: Int, detourMinutes: Int): Int {
    require(percent in 0..100) { "percent must be 0..100: $percent" }
    require(detourMinutes >= 0) { "detourMinutes must not be negative: $detourMinutes" }
    return (percent - maxOf(0, detourMinutes - FREE_DETOUR_MINUTES)).coerceAtLeast(0)
}
