package trip.stop

import trip.i18n.Lang
import trip.i18n.Messages
import trip.place.Fact

/** One line per known fact of [card] that has a dated source, in the card's order: the label, then where and when it was read. */
fun sourceLines(card: StopCard, lang: Lang): List<String> = buildList {
    for ((need, fact) in CARD_NEEDS.zip(card.needs)) {
        sourceLine(Messages.text(lang, "need.${need.name}"), fact, lang)?.let { add(it) }
    }
    sourceLine(Messages.text(lang, "card.price"), card.fee, lang)?.let { add(it) }
    sourceLine(Messages.text(lang, "card.openingHours"), card.openingHours, lang)?.let { add(it) }
}

/** The source line under [label] for [fact], or null when the fact is not known or its source has no date. */
private fun sourceLine(label: String, fact: Fact<*>?, lang: Lang): String? {
    if (fact == null || fact.source.date.isEmpty()) return null
    return Messages.text(
        lang,
        "card.source",
        mapOf("label" to label, "source" to fact.source.name, "date" to fact.source.date),
    )
}
