package trip.net

import trip.place.Place
import trip.place.mergeEquipment
import trip.place.mergeNearby
import trip.plan.Route

/**
 * One Overpass query per window of at most [maxPoints] simplified route points, in route order. Consecutive windows
 * share one boundary point, so every stretch of the route is covered by some query.
 */
fun queryChunks(route: Route, maxPoints: Int = 20, radiusMetres: Int = 2000): List<String> {
    require(maxPoints >= 2)
    val points = simplify(route)
    val step = maxPoints - 1
    return (0 until points.lastIndex step step).map { start ->
        val end = minOf(start + step, points.lastIndex)
        query(Route(points.subList(start, end + 1)), radiusMetres)
    }
}

/**
 * The places of all the results: the first place for each osmId, with the equipment nodes merged into playgrounds within
 * 50 m and dropped, then the toilets merged into nearby places. Equipment goes first, so an equipment node is never the
 * place a toilet merges into.
 */
fun combinePlaces(results: List<List<Place>>): List<Place> =
    mergeNearby(mergeEquipment(results.flatten().distinctBy { it.osmId }))

/** True when Overpass answered with a `remark` about a runtime error, so the elements may be partial. */
fun overpassIncomplete(remark: String?): Boolean = remark != null && remark.contains("runtime error", ignoreCase = true)
