package trip.stop

import trip.Need
import trip.i18n.Lang
import trip.i18n.Messages
import trip.match.AgeFit
import trip.match.Match
import trip.place.Category
import trip.place.Fact
import trip.place.Source
import trip.plan.Stop
import trip.start.formatAge
import trip.start.formatMinutes

/**
 * What the card of a stop shows: the place name (null when unnamed), the detour, the typical time, the match, the needs
 * in the order of [CARD_NEEDS] (null where not known), the fee and the opening hours (null where not known), and the age fit
 * (null where not known).
 */
data class StopCard(
    val title: String?,
    val detourMinutes: Int,
    val typicalMinutes: Fact<Int>,
    val match: Match,
    val needs: List<Fact<Boolean>?>,
    val fee: Fact<Boolean>?,
    val openingHours: Fact<String>?,
    val ageFit: AgeFit? = null,
)

/** One labelled line of the card: its [value] is empty when the fact is not known, and [note] says "derived" or "unknown". */
data class CardLine(val label: String, val value: String, val note: String?)

/** The typical minutes spent at a place of each category. */
private val TYPICAL_MINUTES: Map<Category, Int> = mapOf(
    Category.Play to 30,
    Category.Animals to 90,
    Category.Food to 45,
    Category.IceCream to 15,
    Category.Swimming to 90,
    Category.Nature to 45,
    Category.Museum to 75,
    Category.Indoor to 60,
    Category.Rest to 15,
)

private const val TYPICAL_WITHOUT_CATEGORY = 30

/** The needs on the card, in the order they are shown. */
internal val CARD_NEEDS = listOf(Need.Toilet, Need.ChangingTable, Need.Pram)

/** The source of the typical time: a table of the app, not a reading of the place, so it has no date. */
private val ESTIMATE = Source("Roadpal estimate", "")

/** The card for [stop]. The typical time is the largest of the place's categories, so it is marked derived. */
fun card(stop: Stop): StopCard {
    val place = stop.place
    val minutes = place.categories.maxOfOrNull { TYPICAL_MINUTES.getValue(it) } ?: TYPICAL_WITHOUT_CATEGORY
    return StopCard(
        title = place.name,
        detourMinutes = stop.detourMinutes,
        typicalMinutes = Fact(minutes, ESTIMATE, derived = true),
        match = stop.match,
        needs = CARD_NEEDS.map { place.needs[it] },
        fee = place.fee,
        openingHours = place.openingHours,
        ageFit = stop.match.ageFit,
    )
}

/** The lines of [card] in [lang]: the detour, the typical time, the age fit, the needs, the price and the opening hours. */
fun lines(card: StopCard, lang: Lang): List<CardLine> = buildList {
    add(CardLine(Messages.text(lang, "card.detour"), formatMinutes(card.detourMinutes, lang), null))
    add(factLine(Messages.text(lang, "card.typical"), card.typicalMinutes, lang) { formatMinutes(it, lang) })
    add(ageLine(card.ageFit, lang))
    for ((need, fact) in CARD_NEEDS.zip(card.needs)) {
        add(factLine(Messages.text(lang, "need.${need.name}"), fact, lang) { yesNo(it, lang) })
    }
    add(factLine(Messages.text(lang, "card.price"), card.fee, lang) {
        Messages.text(lang, if (it) "card.fee.paid" else "card.free")
    })
    add(factLine(Messages.text(lang, "card.openingHours"), card.openingHours, lang) { it })
}

/** The line under [label] for [fact]: its value as [value] gives it, with a note when the fact is derived or not known. */
private fun <T> factLine(label: String, fact: Fact<T>?, lang: Lang, value: (T) -> String): CardLine = when {
    fact == null -> CardLine(label, "", Messages.text(lang, "card.unknown"))
    fact.derived -> CardLine(label, value(fact.value), Messages.text(lang, "card.derived"))
    else -> CardLine(label, value(fact.value), null)
}

/** The line of the age fit: its span, and its source and confidence as the note; not known when there is no fit. */
private fun ageLine(fit: AgeFit?, lang: Lang): CardLine {
    val label = Messages.text(lang, "card.age")
    return when (fit) {
        null -> CardLine(label, "", Messages.text(lang, "card.unknown"))
        else -> {
            val span = fit.span
            val value = "${formatAge(span.fromMonths, lang)} – ${formatAge(span.toMonths, lang)}"
            val confidence = Messages.text(lang, "confidence.${fit.confidence.name}")
            val noteKey = if (fit.stated) "card.age.Stated" else "card.age.${fit.source.name}"
            CardLine(label, value, Messages.text(lang, noteKey, mapOf("confidence" to confidence)))
        }
    }
}

private fun yesNo(value: Boolean, lang: Lang): String = Messages.text(lang, if (value) "card.yes" else "card.no")
