package trip.net

/** Reads JSON text into null, Map, List, String, Double or Boolean values; throws IllegalArgumentException on malformed text. */
fun parseJson(text: String): Any? = JsonReader(text).read()

private const val MAX_DEPTH = 200

private val SIMPLE_ESCAPES = mapOf(
    '"' to '"',
    '\\' to '\\',
    '/' to '/',
    'b' to '\b',
    'f' to '\u000C',
    'n' to '\n',
    'r' to '\r',
    't' to '\t',
)

private class JsonReader(private val text: String) {
    private var pos = 0
    private var depth = 0

    fun read(): Any? {
        val value = parseValue()
        skipWhitespace()
        if (pos < text.length) fail("unexpected text after value")
        return value
    }

    private fun parseValue(): Any? {
        skipWhitespace()
        val c = peek() ?: fail("unexpected end of text")
        return when {
            c == '{' -> nested { parseObject() }
            c == '[' -> nested { parseArray() }
            c == '"' -> parseString()
            c == '-' || c in '0'..'9' -> parseNumber()
            c == 't' -> parseLiteral("true", true)
            c == 'f' -> parseLiteral("false", false)
            c == 'n' -> parseLiteral("null", null)
            else -> fail("unexpected character")
        }
    }

    private inline fun <T> nested(parse: () -> T): T {
        depth++
        if (depth > MAX_DEPTH) fail("nesting too deep")
        val result = parse()
        depth--
        return result
    }

    private fun parseObject(): Map<String, Any?> {
        pos++
        val result = LinkedHashMap<String, Any?>()
        skipWhitespace()
        if (peek() == '}') {
            pos++
            return result
        }
        while (true) {
            skipWhitespace()
            if (peek() != '"') fail("expected a string key")
            val key = parseString()
            skipWhitespace()
            if (peek() != ':') fail("expected ':'")
            pos++
            result[key] = parseValue()
            skipWhitespace()
            when (peek()) {
                ',' -> pos++
                '}' -> {
                    pos++
                    return result
                }
                else -> fail("expected ',' or '}'")
            }
        }
    }

    private fun parseArray(): List<Any?> {
        pos++
        val result = ArrayList<Any?>()
        skipWhitespace()
        if (peek() == ']') {
            pos++
            return result
        }
        while (true) {
            result.add(parseValue())
            skipWhitespace()
            when (peek()) {
                ',' -> pos++
                ']' -> {
                    pos++
                    return result
                }
                else -> fail("expected ',' or ']'")
            }
        }
    }

    private fun parseString(): String {
        pos++
        val out = StringBuilder()
        while (true) {
            if (pos >= text.length) fail("unterminated string")
            val c = text[pos]
            when {
                c == '"' -> {
                    pos++
                    return out.toString()
                }
                c == '\\' -> {
                    pos++
                    out.append(parseEscape())
                }
                c < ' ' -> fail("control character in string")
                else -> {
                    out.append(c)
                    pos++
                }
            }
        }
    }

    private fun parseEscape(): Char {
        if (pos >= text.length) fail("unterminated string")
        val c = text[pos]
        if (c == 'u') {
            pos++
            return parseUnicodeEscape()
        }
        val mapped = SIMPLE_ESCAPES[c] ?: fail("unknown escape")
        pos++
        return mapped
    }

    private fun parseUnicodeEscape(): Char {
        var code = 0
        repeat(4) {
            if (pos >= text.length) fail("unterminated string")
            val digit = hexValue(text[pos])
            if (digit < 0) fail("expected four hex digits")
            code = code * 16 + digit
            pos++
        }
        return code.toChar()
    }

    private fun parseNumber(): Double {
        val start = pos
        if (peek() == '-') pos++
        if (peek() == '0') {
            pos++
        } else {
            requireDigit()
            while (isDigit(peek())) pos++
        }
        if (peek() == '.') {
            pos++
            requireDigit()
            while (isDigit(peek())) pos++
        }
        if (peek() == 'e' || peek() == 'E') {
            pos++
            if (peek() == '+' || peek() == '-') pos++
            requireDigit()
            while (isDigit(peek())) pos++
        }
        return text.substring(start, pos).toDouble()
    }

    private fun requireDigit() {
        if (!isDigit(peek())) fail("expected a digit")
    }

    private fun parseLiteral(word: String, value: Any?): Any? {
        for (expected in word) {
            if (peek() != expected) fail("invalid literal")
            pos++
        }
        return value
    }

    private fun skipWhitespace() {
        while (pos < text.length) {
            val c = text[pos]
            if (c != ' ' && c != '\t' && c != '\n' && c != '\r') return
            pos++
        }
    }

    private fun peek(): Char? = if (pos < text.length) text[pos] else null

    private fun isDigit(c: Char?): Boolean = c != null && c in '0'..'9'

    private fun hexValue(c: Char): Int = when (c) {
        in '0'..'9' -> c - '0'
        in 'a'..'f' -> c - 'a' + 10
        in 'A'..'F' -> c - 'A' + 10
        else -> -1
    }

    private fun fail(reason: String): Nothing =
        throw IllegalArgumentException("Invalid JSON at $pos: $reason")
}
