package trip.net

import trip.start.DEMO_DESTINATION
import trip.start.DEMO_START

private val SAVED_PLACES = listOf(
    DEMO_START to listOf("stockholm"),
    DEMO_DESTINATION to listOf("göteborg", "goteborg", "gothenburg"),
)

/** The demo's two saved places (the city-centre values of the demo trip), used only by the demo mode without a network, never invented for other places. */
fun savedSearch(query: String): List<Found> {
    val normalized = query.trim().lowercase()
    if (normalized.isEmpty()) return emptyList()
    return SAVED_PLACES
        .filter { (_, names) -> names.any { it.startsWith(normalized) } }
        .map { (place, _) -> place }
}
