package trip.plan

import trip.Family
import trip.place.Place

/** The answer to "we need a break now": the position is too far from the route, or the best stops ahead (maybe none). */
sealed interface PauseResult {
    data object OffRoute : PauseResult

    data class Stops(val stops: List<Stop>) : PauseResult
}

private const val MAX_OFF_ROUTE_METRES = 2000.0

/**
 * The best stops within [withinMinutes] ahead of the route point nearest ([lat], [lon]), best first, at most [limit],
 * with [filter] applied. A position more than 2 km from the route is [PauseResult.OffRoute].
 */
fun pauseNow(
    route: Route,
    places: List<Place>,
    family: Family,
    filter: StopFilter,
    lat: Double,
    lon: Double,
    withinMinutes: Int = 15,
    limit: Int = 3,
): PauseResult {
    val (index, distance) = route.nearest(lat, lon)
    if (distance > MAX_OFF_ROUTE_METRES) return PauseResult.OffRoute
    return PauseResult.Stops(nearNow(route, route.points[index].seconds, places, family, withinMinutes, limit, filter))
}
