package trip.net

import kotlin.js.Promise

/**
 * Fetches the saved route and then the saved places, one after the other, and reads them into the demo data.
 * Any failure, including a file that does not read, rejects with the Messages key "error.saved" and nothing else.
 */
fun fetchSavedDemo(fetchText: (path: String) -> Promise<String>): Promise<SavedDemoData> {
    // Starting from a resolved promise turns a synchronous throw from fetchText into a rejection.
    val routeText: Promise<String> = Promise.resolve(Unit).then { fetchText(SAVED_ROUTE_PATH).asDynamic() }
    val demo: Promise<SavedDemoData> = routeText.then { route ->
        // JS waits for a returned Promise, so the places file is asked for only after the route has answered.
        fetchText(SAVED_PLACES_PATH).then { places -> savedDemoData(route, places) }.asDynamic()
    }
    return demo.catch { throw Throwable("error.saved") }
}
