package trip.net

import trip.place.Place
import trip.place.Source
import trip.plan.Route
import kotlin.js.Promise

/** The places for a plan; [saved] is the source of the saved answer when it stands in for the live one, else null. */
data class PlacesAnswer(val places: List<Place>, val saved: Source?)

/** Live places when the live query works; otherwise the saved demo places for a demo-shaped route, else the original live error. */
fun placesOrSaved(route: Route, live: () -> Promise<List<Place>>, saved: SavedDemoLoader): Promise<PlacesAnswer> =
    Promise.resolve(Unit).then { _ -> live() }.then(
        { places -> Promise.resolve(PlacesAnswer(places, null)) },
        { e ->
            // The route is checked before the saved files are asked for, so a route that does not fit fetches nothing.
            if (!useSavedPlaces(route, liveFailed = true, savedAvailable = true)) throw e
            saved.load().then(
                { data -> PlacesAnswer(data.places, data.placesSource) },
                { _ -> throw e },
            )
        },
    ).then { answer -> answer }
