package trip.place

import kotlin.math.PI
import kotlin.math.asin
import kotlin.math.cos
import kotlin.math.sin
import kotlin.math.sqrt

private const val EARTH_RADIUS_METRES = 6_371_000.0

/** The great-circle distance in metres between two points given in degrees, by the haversine formula. */
fun distanceMetres(lat1: Double, lon1: Double, lat2: Double, lon2: Double): Double {
    val dLat = radians(lat2 - lat1)
    val dLon = radians(lon2 - lon1)
    val h = sin(dLat / 2) * sin(dLat / 2) + cos(radians(lat1)) * cos(radians(lat2)) * sin(dLon / 2) * sin(dLon / 2)
    return 2 * EARTH_RADIUS_METRES * asin(sqrt(h))
}

private fun radians(degrees: Double): Double = degrees * PI / 180.0
