package trip.plan

/** A stretch of the route, in seconds from the start, that has no stop within the longest drive. */
data class Stretch(val fromSeconds: Int, val toSeconds: Int)

private const val END_TOLERANCE_SECONDS = 600

/**
 * The stretches of a route that are longer than the longest drive between neighbouring boundaries. The boundaries are
 * the route start, the stops in sorted order, and the route end. A stretch is a pair whose gap is over the drive. The
 * last pair, up to the route end, may run [END_TOLERANCE_SECONDS] longer, because [StopPlanner] stops planning when
 * fewer than that remain. Returns the stretches in route order.
 */
fun uncoveredStretches(totalSeconds: Int, stopSeconds: List<Int>, maxDriveMinutes: Int): List<Stretch> {
    require(totalSeconds > 0) { "totalSeconds must be positive, was $totalSeconds" }
    require(maxDriveMinutes > 0) { "maxDriveMinutes must be positive, was $maxDriveMinutes" }
    stopSeconds.forEach { require(it in 0..totalSeconds) { "stop at $it seconds is outside the route" } }
    val boundaries = listOf(0) + stopSeconds.sorted() + totalSeconds
    val driveSeconds = maxDriveMinutes * 60
    return boundaries.zipWithNext().mapIndexedNotNull { index, (from, to) ->
        val limit = if (index == boundaries.size - 2) driveSeconds + END_TOLERANCE_SECONDS else driveSeconds
        if (to - from > limit) Stretch(from, to) else null
    }
}
