package trip.start

import trip.i18n.Lang
import trip.i18n.Messages

/** A duration in minutes as "1 h 30 min", "45 min" or "2 h" in [lang]; the unit words come from [Messages]. */
fun formatMinutes(minutes: Int, lang: Lang): String {
    val hours = minutes / 60
    val rest = minutes % 60
    val hourText = "$hours ${Messages.text(lang, "unit.hours")}"
    val minuteText = "$rest ${Messages.text(lang, "unit.minutes")}"
    return when {
        hours == 0 -> minuteText
        rest == 0 -> hourText
        else -> "$hourText $minuteText"
    }
}

/** An age in months as "2 years 3 months" in [lang]; a zero year or month is left out, unless the age is under a year. */
fun formatAge(months: Int, lang: Lang): String {
    val years = months / 12
    val rest = months % 12
    val parts = buildList {
        if (years > 0) add("$years ${Messages.text(lang, if (years == 1) "unit.year" else "unit.years")}")
        if (rest > 0 || years == 0) add("$rest ${Messages.text(lang, if (rest == 1) "unit.month" else "unit.months")}")
    }
    return parts.joinToString(" ")
}
