package trip.start

/** The network error keys: when the device is offline these become error.offline. */
private val networkErrorKeys = setOf("error.route", "error.places", "error.placesIncomplete", "error.search")

/** The message key for a failed plan or search: error.offline when the device is not [online] and [errorKey] is a network error, else [errorKey]. */
fun failureKey(errorKey: String, online: Boolean): String =
    if (!online && errorKey in networkErrorKeys) "error.offline" else errorKey
