package trip.net

import kotlin.js.Promise

/**
 * Asks for each of [items] in turn, never in parallel: the ask for an item starts only after the one before has answered.
 * A failed ask is retried after the pause that [retryDelayMs] gives it; when that gives none, the failure is passed on.
 * [pause] resolves after the given milliseconds. [onProgress] is called with 0 and the number of items before the first
 * ask, and with the number answered after each answer; retries are not counted. Resolves with the answers in order.
 */
fun <T, R> askInOrder(
    items: List<T>,
    ask: (T) -> Promise<R>,
    pause: (ms: Int) -> Promise<Unit>,
    onProgress: (done: Int, total: Int) -> Unit,
): Promise<List<R>> {
    fun askWithRetry(item: T, failed: Int): Promise<R> =
        ask(item).catch { error ->
            val delay = retryDelayMs(failed + 1) ?: throw error
            // JS waits for a returned Promise, so the retry starts only after the pause.
            pause(delay.toInt()).then { askWithRetry(item, failed + 1) }.asDynamic()
        }

    onProgress(0, items.size)
    return items.foldIndexed(Promise.resolve(emptyList<R>())) { index, chain, item ->
        // JS waits for a returned Promise, so each ask starts only after the one before has answered.
        chain.then { answers ->
            askWithRetry(item, 0).then { answer ->
                onProgress(index + 1, items.size)
                answers + listOf(answer)
            }.asDynamic()
        }
    }
}
