package trip.net

import trip.i18n.Lang
import trip.i18n.Messages
import trip.place.Source

/** The plain on-screen notice that saved data is in use, with its source and the date it was read (`YYYY-MM-DD`). */
fun savedNotice(lang: Lang, source: Source): String =
    Messages.text(lang, "saved.notice", mapOf("source" to source.name, "date" to source.date))
