package trip.place

import trip.Need

/**
 * The place for [e]: the [OsmPlaces.fromElement] place when it has a category, else a toilet place for a public
 * `amenity=toilets` node or way, else null. A toilet has no category, so it is a place only until [mergeNearby] folds it
 * into a nearby place or [withoutLoneToilets] drops it. An element with no category but a `playground=*` tag is an
 * equipment-only place until [mergeEquipment] folds it into a playground.
 */
fun placeOrToilet(e: OsmElement, source: Source): Place? {
    OsmPlaces.fromElement(e, source)?.let { return it }
    equipmentPlace(e)?.let { return it }
    val tags = e.tags
    if (tags["amenity"] != "toilets" || tags["access"] in listOf("private", "no", "customers")) return null
    return Place(
        osmId = "${e.type}/${e.id}",
        name = tags["name"],
        lat = e.lat,
        lon = e.lon,
        categories = emptySet(),
        needs = mapOf(Need.Toilet to Fact(true, source)),
        openingHours = tags["opening_hours"]?.let { Fact(it, source) },
        fee = null,
        equipment = emptyList(),
    )
}

/**
 * The places with at least one category. Call it after [mergeNearby]: a toilet left with no place within 30 m is not a
 * stop.
 */
fun withoutLoneToilets(places: List<Place>): List<Place> = places.filter { it.categories.isNotEmpty() }
