package trip.start

import trip.AgeGroup
import trip.AgeSpan
import trip.Child
import trip.net.Found
import trip.place.Category
import trip.plan.StopFilter

/** The demo journey's start: the city centre of Stockholm. */
val DEMO_START = Found("Stockholm", 59.3293, 18.0686)

/** The demo journey's destination: the city centre of Göteborg. */
val DEMO_DESTINATION = Found("Göteborg", 57.7089, 11.9746)

/** The demo journey's longest drive between stops in minutes. */
const val DEMO_DRIVE_MINUTES = 90

/** The start form of the demo journey: Stockholm to Göteborg with a baby and a preschooler. */
fun demoForm(): StartForm = StartForm(
    start = DEMO_START,
    destination = DEMO_DESTINATION,
    children = listOf(Child.InSpan(AgeSpan.of(AgeGroup.Baby)), Child.InSpan(AgeSpan.of(AgeGroup.Preschool))),
    maxDriveMinutes = DEMO_DRIVE_MINUTES,
    needs = emptySet(),
)

/** The stop filter of the demo journey: play places. */
fun demoFilter(): StopFilter = StopFilter(categories = setOf(Category.Play))
