package trip.place

import trip.Need

/** Builds places from OpenStreetMap tags. Every fact keeps the [Source] it was read from. */
object OsmPlaces {
    /** The place for [e], or null when its tags give no category. */
    fun fromElement(e: OsmElement, source: Source): Place? {
        val tags = e.tags
        val categories = categories(tags)
        if (categories.isEmpty()) return null
        return Place(
            osmId = "${e.type}/${e.id}",
            name = tags["name"],
            lat = e.lat,
            lon = e.lon,
            categories = categories,
            needs = needs(tags, categories, source),
            openingHours = tags["opening_hours"]?.let { Fact(it, source) },
            fee = yesNo(tags["fee"])?.let { Fact(it, source) },
            equipment = equipment(tags),
            statedAge = osmAgeSpan(tags["min_age"], tags["max_age"])?.let { Fact(it, source) },
        )
    }

    private fun categories(tags: Map<String, String>): Set<Category> {
        val amenity = tags["amenity"]
        val leisure = tags["leisure"]
        val tourism = tags["tourism"]
        val highway = tags["highway"]
        val cuisines = cuisines(tags)
        val result = mutableSetOf<Category>()
        if (leisure == "playground") result += Category.Play
        if (tourism == "zoo" || tourism == "aquarium" || tags.containsKey("zoo")) result += Category.Animals
        if (amenity in listOf("restaurant", "fast_food", "cafe")) result += Category.Food
        if (amenity == "ice_cream" || "ice_cream" in cuisines) result += Category.IceCream
        if (leisure in listOf("swimming_pool", "water_park", "beach_resort") || tags["natural"] == "beach") result += Category.Swimming
        if (leisure in listOf("nature_reserve", "park")) result += Category.Nature
        if (tourism == "museum") result += Category.Museum
        val building = tags["building"] == "yes"
        if (tags["indoor"] == "yes" || (building && (Category.Play in result || Category.Museum in result)) || leisure == "indoor_play") {
            result += Category.Indoor
        }
        if (highway in listOf("rest_area", "services") || tourism == "picnic_site") result += Category.Rest
        return result
    }

    private fun needs(tags: Map<String, String>, categories: Set<Category>, source: Source): Map<Need, Fact<Boolean>> {
        val needs = mutableMapOf<Need, Fact<Boolean>>()
        fun put(need: Need, value: Boolean?, derived: Boolean = false) {
            if (value != null) needs[need] = Fact(value, source, derived)
        }
        put(Need.Toilet, if (tags["amenity"] == "toilets") true else yesNo(tags["toilets"]))
        put(Need.ChangingTable, yesNo(tags["changing_table"]) ?: yesNo(tags["diaper"]))
        when (tags["wheelchair"]) {
            "yes" -> put(Need.Pram, true, derived = true)
            "limited", "no" -> put(Need.Pram, false, derived = true)
        }
        if (Category.Food in categories || Category.IceCream in categories) put(Need.Food, true, derived = true)
        if (tags["amenity"] == "cafe" || "coffee_shop" in cuisines(tags)) put(Need.Coffee, true, derived = true)
        if (tags["amenity"] == "charging_station") put(Need.Charging, true)
        put(Need.Free, yesNo(tags["fee"])?.let { !it })
        if (Category.Indoor in categories) put(Need.Indoor, true, derived = true)
        return needs
    }

    /** The equipment of a playground: the values of `playground=*` and the `<x>` of each `playground:<x>=yes|<n>`. */
    private fun equipment(tags: Map<String, String>): List<String> {
        if (tags["leisure"] != "playground") return emptyList()
        val fromValue = tags["playground"]?.split(";").orEmpty()
        val fromKeys = tags
            .filter { (key, value) -> key.startsWith("playground:") && (value == "yes" || value.toIntOrNull() != null) }
            .keys.map { it.removePrefix("playground:") }
        return (fromValue + fromKeys).map { it.trim() }.filter { it.isNotEmpty() }.distinct().sorted()
    }

    private fun cuisines(tags: Map<String, String>): List<String> =
        tags["cuisine"]?.split(";")?.map { it.trim() }.orEmpty()

    private fun yesNo(value: String?): Boolean? = when (value) {
        "yes" -> true
        "no" -> false
        else -> null
    }
}

/**
 * Adds each toilet node to the nearest other place within [metres] of it, as Toilet true (not derived). A toilet with
 * no place within [metres] stays a place of its own.
 */
fun mergeNearby(places: List<Place>, metres: Double = 30.0): List<Place> {
    val result = places.filterNot { isToilet(it) }.toMutableList()
    val alone = mutableListOf<Place>()
    for (toilet in places.filter { isToilet(it) }) {
        val index = result.indices
            .filter { metresBetween(result[it], toilet) <= metres }
            .minByOrNull { metresBetween(result[it], toilet) }
        if (index == null) {
            alone += toilet
        } else {
            val place = result[index]
            result[index] = place.copy(needs = place.needs + (Need.Toilet to toilet.needs.getValue(Need.Toilet)))
        }
    }
    return result + alone
}

/** A toilet node: a place with no category of its own that has Toilet true. */
private fun isToilet(place: Place): Boolean = place.categories.isEmpty() && place.needs[Need.Toilet]?.value == true

private fun metresBetween(a: Place, b: Place): Double = distanceMetres(a.lat, a.lon, b.lat, b.lon)
