package trip.net

import trip.plan.Route

/** The route of a live OSRM answer given as JSON [text]; any failure throws IllegalArgumentException with the message key `error.route`. */
fun liveRoute(text: String): Route =
    try {
        savedRoute(parseJson(text))
    } catch (e: IllegalArgumentException) {
        throw IllegalArgumentException("error.route", e)
    }
