package trip.net

import trip.place.distanceMetres
import trip.plan.Route

private const val SAVED_DEMO_RADIUS_METRES = 25_000.0

private val STOCKHOLM_LAT = 59.3293
private val STOCKHOLM_LON = 18.0686
private val GOTEBORG_LAT = 57.7089
private val GOTEBORG_LON = 11.9746

/** True when [route] runs between Stockholm and Göteborg, in either direction: each end is within 25 km of a city centre. */
fun fitsSavedDemoRoute(route: Route): Boolean {
    val first = route.points.first()
    val last = route.points.last()
    val firstInStockholm = within(first.lat, first.lon, STOCKHOLM_LAT, STOCKHOLM_LON)
    val firstInGoteborg = within(first.lat, first.lon, GOTEBORG_LAT, GOTEBORG_LON)
    val lastInStockholm = within(last.lat, last.lon, STOCKHOLM_LAT, STOCKHOLM_LON)
    val lastInGoteborg = within(last.lat, last.lon, GOTEBORG_LAT, GOTEBORG_LON)
    return (firstInStockholm && lastInGoteborg) || (firstInGoteborg && lastInStockholm)
}

private fun within(lat: Double, lon: Double, centreLat: Double, centreLon: Double): Boolean =
    distanceMetres(lat, lon, centreLat, centreLon) <= SAVED_DEMO_RADIUS_METRES
