package trip.start

import trip.AgeGroup
import trip.AgeSpan
import trip.Child
import trip.Family
import trip.Need
import trip.i18n.Lang
import trip.i18n.Messages
import trip.net.Found
import trip.place.distanceMetres

/** The drive presets of the start screen in minutes; any other drive is a custom one. */
val DRIVE_PRESETS = listOf(30, 60, 90, 120)

/** A start and a destination closer than this are one place, not a trip. */
private const val MIN_TRIP_METRES = 1000.0

/** What the family enters on the start screen. Nothing here is stored. */
data class StartForm(
    val start: Found? = null,
    val destination: Found? = null,
    val children: List<Child> = emptyList(),
    val maxDriveMinutes: Int? = null,
    val needs: Set<Need> = emptySet(),
)

/** The message keys for what is missing or wrong in [form], in screen order; empty when the form is complete. */
fun check(form: StartForm): List<String> = buildList {
    val start = form.start
    val destination = form.destination
    if (start == null) add("start.error.start")
    if (destination == null) add("start.error.destination")
    if (start != null && destination != null &&
        distanceMetres(start.lat, start.lon, destination.lat, destination.lon) < MIN_TRIP_METRES
    ) {
        add("start.error.same")
    }
    if (form.children.isEmpty()) add("start.error.children")
    val drive = form.maxDriveMinutes
    if (drive == null || drive !in 15..300) add("start.error.drive")
}

/** The family of a complete [form]. Throws when [check] finds something missing or wrong. */
fun family(form: StartForm): Family {
    val missing = check(form)
    require(missing.isEmpty()) { "The start form is incomplete: $missing" }
    return Family(children = form.children, needs = form.needs, maxDriveMinutes = checkNotNull(form.maxDriveMinutes))
}

/** A child whose age is from [fromYears] and [fromMonths] up to [toYears] and [toMonths], or null when it ends before it starts. */
fun customChild(fromYears: Int, fromMonths: Int, toYears: Int, toMonths: Int): Child? {
    val from = fromYears * 12 + fromMonths
    val to = toYears * 12 + toMonths
    return if (from in 0..to) Child.InSpan(AgeSpan(from, to)) else null
}

/** A child's age in [lang]: the name of its age group when the span is one, else the age or the span. */
fun childLabel(child: Child, lang: Lang): String {
    val span = child.span()
    val group = AgeGroup.entries.firstOrNull { AgeSpan.of(it) == span }
    return when {
        group != null -> Messages.text(lang, "ageGroup.${group.name}")
        span.fromMonths == span.toMonths -> formatAge(span.fromMonths, lang)
        else -> Messages.text(
            lang,
            "start.child.span",
            mapOf("from" to formatAge(span.fromMonths, lang), "to" to formatAge(span.toMonths, lang)),
        )
    }
}
