package trip.net

import trip.plan.Route
import trip.plan.RoutePoint
import kotlin.math.abs
import kotlin.math.round
import kotlin.math.roundToInt

/** The OSRM demo server's driving route service: the routing host the app uses (see AGENTS.md). */
private const val OSRM_DRIVING = "https://router.project-osrm.org/route/v1/driving"

/** The URL of the driving route from ([fromLat], [fromLon]) to ([toLat], [toLon]), as GeoJSON with the duration of each segment. */
fun routeUrl(fromLat: Double, fromLon: Double, toLat: Double, toLon: Double): String =
    "$OSRM_DRIVING/${coordinate(fromLon)},${coordinate(fromLat)};${coordinate(toLon)},${coordinate(toLat)}" +
        "?overview=full&geometries=geojson&annotations=duration"

/**
 * The route through GeoJSON [coordinates] (`[lon, lat]` pairs), where [durations] are the seconds of each segment
 * between them. Each point's seconds are the running total of the durations, in whole seconds. A route needs rising
 * seconds and OSRM's dense geometry has segments under a second, so a point whose seconds do not rise above the last
 * kept point is dropped; the final point is always kept, replacing the last kept point when their seconds are equal
 * (or, when the whole route rounds to 0 seconds, getting 1 second).
 */
fun routeFrom(coordinates: List<List<Double>>, durations: List<Double>): Route {
    require(coordinates.size >= 2) { "A route needs at least two points, was ${coordinates.size}" }
    require(coordinates.all { it.size == 2 }) { "Each route coordinate is a [lon, lat] pair" }
    require(durations.size == coordinates.size - 1) {
        "A route of ${coordinates.size} points needs ${coordinates.size - 1} durations, was ${durations.size}"
    }
    val kept = mutableListOf(RoutePoint(coordinates[0][1], coordinates[0][0], 0))
    var total = 0.0
    for (i in 1..coordinates.lastIndex) {
        total += durations[i - 1]
        val seconds = total.roundToInt()
        val point = RoutePoint(coordinates[i][1], coordinates[i][0], seconds)
        val last = kept.last()
        when {
            seconds > last.seconds -> kept += point
            i < coordinates.lastIndex -> {}
            kept.size > 1 -> kept[kept.lastIndex] = point
            else -> kept += point.copy(seconds = last.seconds + 1)
        }
    }
    return Route(kept)
}

/** A coordinate in degrees with at most six decimals and `.` as the decimal separator, on every platform. */
internal fun coordinate(degrees: Double): String {
    val micro = round(degrees * 1_000_000).toLong()
    val magnitude = abs(micro)
    val whole = magnitude / 1_000_000
    val fraction = (magnitude % 1_000_000).toString().padStart(6, '0').trimEnd('0')
    val sign = if (micro < 0) "-" else ""
    return if (fraction.isEmpty()) "$sign$whole" else "$sign$whole.$fraction"
}
