package trip.web

import kotlinx.browser.window
import kotlin.js.Date
import kotlin.js.Promise
import trip.i18n.Lang
import trip.net.Found
import trip.net.OVERPASS_URL
import trip.net.PLACES_TIMEOUT_MS
import trip.net.ROUTE_TIMEOUT_MS
import trip.net.SEARCH_TIMEOUT_MS
import trip.net.askInOrder
import trip.net.combinePlaces
import trip.net.liveFounds
import trip.net.livePlaces
import trip.net.liveRoute
import trip.net.queryChunks
import trip.net.routeUrl
import trip.net.searchUrl
import trip.place.Place
import trip.place.Source
import trip.place.withoutLoneToilets
import trip.plan.Route

// Fetches the route, the places and the search results and hands the parsed values to shared. A failure rejects with a
// Messages key.

/** The route from ([fromLat], [fromLon]) to ([toLat], [toLon]); rejects with the key `error.route`. */
fun fetchRoute(fromLat: Double, fromLon: Double, toLat: Double, toLon: Double): Promise<Route> =
    request(routeUrl(fromLat, fromLon, toLat, toLon), js("({})"), "error.route", ROUTE_TIMEOUT_MS) { text ->
        liveRoute(text)
    }

/**
 * The places of the categories and toilets near [route]; rejects with the key `error.places`, or with
 * `error.placesIncomplete` when Overpass answered only part of a query. [onProgress] gets the number of queries answered
 * and the number of queries, first with none answered.
 */
fun fetchPlaces(route: Route, onProgress: (done: Int, total: Int) -> Unit = { _, _ -> }): Promise<List<Place>> =
    askInOrder(queryChunks(route), { chunk -> fetchChunk(chunk) }, ::pause, onProgress)
        .then { lists -> withoutLoneToilets(combinePlaces(lists)) }

/** The text of the file at [path], relative to the page; rejects when the response is not ok. */
fun fetchSavedText(path: String): Promise<String> =
    window.fetch(path)
        .then { response ->
            if (!response.ok) throw IllegalStateException("HTTP ${response.status}")
            response.text()
        }
        .then { text -> text }

/** The places of one Overpass query; [askInOrder] sends the queries one after another and retries a failed one. */
private fun fetchChunk(chunk: String): Promise<List<Place>> {
    val options: dynamic = js("({})")
    options.method = "POST"
    options.headers = js("({'Content-Type': 'application/x-www-form-urlencoded'})")
    options.body = "data=" + encodeURIComponent(chunk)
    return request(OVERPASS_URL, options, "error.places", PLACES_TIMEOUT_MS) { text ->
        livePlaces(text, Source("OpenStreetMap", Date().toISOString().substringBefore("T")))
    }
}

/** Resolves after [ms] milliseconds. */
private fun pause(ms: Int): Promise<Unit> = Promise<Unit> { resolve, _ ->
    window.setTimeout({ resolve(Unit) }, ms)
}

/** When the last search request was sent, in milliseconds since 1970. */
private var lastSearch = 0.0

/**
 * The places matching [text] in [lang]. Nominatim allows one request a second, so a search within a second of the last
 * one waits for the second to pass; a failed request rejects with the key `error.search`. Blank text throws.
 */
fun searchPlaces(text: String, lang: Lang): Promise<List<Found>> {
    val url = searchUrl(text, lang)
    val now = Date.now()
    val start = maxOf(now, lastSearch + 1000)
    lastSearch = start
    return Promise<List<Found>> { resolve, reject ->
        window.setTimeout(
            {
                request(url, js("({})"), "error.search", SEARCH_TIMEOUT_MS) { answer -> liveFounds(answer) }
                    .then(resolve, reject)
            },
            (start - now).toInt(),
        )
    }
}

private fun encodeURIComponent(text: String): String = js("encodeURIComponent")(text) as String

/**
 * Calls [url] and parses the response text with [parse]; gives up after [timeoutMs] milliseconds. Any failure, including
 * the timeout, rejects with the message key [errorKey].
 */
private fun <T> request(
    url: String,
    options: dynamic,
    errorKey: String,
    timeoutMs: Int,
    parse: (String) -> T,
): Promise<T> {
    val controller: dynamic = js("new AbortController()")
    options.signal = controller.signal
    val timer = window.setTimeout({ controller.abort() }, timeoutMs)
    return window.fetch(url, options)
        .then { response ->
            if (!response.ok) throw IllegalStateException("HTTP ${response.status}")
            response.text()
        }
        .then { text ->
            window.clearTimeout(timer)
            parse(text)
        }
        .catch { e ->
            window.clearTimeout(timer)
            throw if ((e as? Throwable)?.message == "error.placesIncomplete") e else Throwable(errorKey)
        }
}
