package trip.net

import trip.place.OsmElement
import trip.place.Place
import trip.place.Source
import trip.place.placeOrToilet
import trip.place.withoutLoneToilets
import trip.plan.Route

/** The route of a parsed saved OSRM answer: the first route's coordinates and the duration of each of its segments. */
fun savedRoute(osrm: Any?): Route {
    require(osrm is Map<*, *>) { "Saved OSRM answer is not an object" }
    require(osrm["code"] == "Ok") { "Saved OSRM answer has code ${osrm["code"]}" }
    val route = (osrm["routes"] as? List<*>)?.firstOrNull() as? Map<*, *> ?: throw osrmMissing("routes[0]")
    val geometry = route["geometry"] as? Map<*, *> ?: throw osrmMissing("geometry.coordinates")
    val points = geometry["coordinates"] as? List<*> ?: throw osrmMissing("geometry.coordinates")
    val coordinates = points.map { numbers(it, "geometry.coordinates") }
    val leg = (route["legs"] as? List<*>)?.firstOrNull() as? Map<*, *> ?: throw osrmMissing("legs[0]")
    val annotation = leg["annotation"] as? Map<*, *> ?: throw osrmMissing("annotation.duration")
    return routeFrom(coordinates, numbers(annotation["duration"], "annotation.duration"))
}

private fun osrmMissing(path: String) = IllegalArgumentException("Saved OSRM answer has no $path")

private fun numbers(value: Any?, path: String): List<Double> {
    val list = value as? List<*> ?: throw osrmMissing(path)
    return list.map { it as? Double ?: throw osrmMissing(path) }
}

/**
 * The elements of a parsed saved Overpass answer, in order, each with its position. An answer whose remark reports a
 * runtime error is refused, because its elements may be partial.
 */
fun savedElements(overpass: Any?): List<OsmElement> {
    require(overpass is Map<*, *>) { "Saved Overpass answer is not an object" }
    require(!overpassIncomplete(overpass["remark"] as? String)) { "Saved Overpass answer is incomplete" }
    val elements = overpass["elements"] as? List<*>
        ?: throw IllegalArgumentException("Saved Overpass answer has no elements")
    return elements.mapIndexedNotNull { index, element -> savedElement(element, index) }
}

private fun savedElement(element: Any?, index: Int): OsmElement? {
    val map = element as? Map<*, *> ?: throw malformedElement(index)
    val type = map["type"] as? String ?: throw malformedElement(index)
    val id = (map["id"] as? Double ?: throw malformedElement(index)).toLong()
    val center = map["center"] as? Map<*, *>
    return elementFrom(
        type,
        id,
        map["lat"] as? Double,
        map["lon"] as? Double,
        center?.get("lat") as? Double,
        center?.get("lon") as? Double,
        savedTags(map["tags"], index),
    )
}

private fun savedTags(value: Any?, index: Int): Map<String, String> {
    if (value == null) return emptyMap()
    val tags = value as? Map<*, *> ?: throw malformedElement(index)
    return tags.entries.associate { (key, tag) ->
        (key as? String ?: throw malformedElement(index)) to (tag as? String ?: throw malformedElement(index))
    }
}

private fun malformedElement(index: Int) = IllegalArgumentException("Saved Overpass element $index is malformed")

/** The places of a parsed saved Overpass answer, as one live answer gives them: toilets merged, lone toilets left out. */
fun savedPlaces(overpass: Any?, source: Source): List<Place> =
    withoutLoneToilets(combinePlaces(listOf(savedElements(overpass).mapNotNull { placeOrToilet(it, source) })))
