package trip

/** A child's age group from the brief's Family Match, in months: what a stop must offer depends on it. */
enum class AgeGroup(val minMonths: Int, val maxMonthsExclusive: Int) {
    Baby(0, 36),
    Preschool(36, 72),
    Young(72, 108),
    Middle(108, 156),
    Teen(156, 192),
    Adult(192, Int.MAX_VALUE);

    companion object {
        fun ofMonths(months: Int): AgeGroup {
            require(months >= 0) { "Age in months must be 0 or more, was $months" }
            return entries.first { months >= it.minMonths && months < it.maxMonthsExclusive }
        }
    }
}
