package trip.net

import trip.place.Source

/** The source and read date from a saved file's header, or null when the source is blank or the date is not a `YYYY-MM-DD` date. */
fun savedSource(source: String?, date: String?): Source? {
    val name = source?.trim()
    val day = date?.trim()
    if (name.isNullOrEmpty() || day == null || !isDate(day)) return null
    return Source(name, day)
}

private fun isDate(text: String): Boolean {
    if (text.length != 10 || text[4] != '-' || text[7] != '-') return false
    for (i in text.indices) {
        if (i != 4 && i != 7 && text[i] !in '0'..'9') return false
    }
    val month = text.substring(5, 7).toInt()
    val day = text.substring(8, 10).toInt()
    return month in 1..12 && day in 1..31
}
