package trip.place

import trip.AgeSpan
import kotlin.math.roundToInt

/**
 * The ages an OSM place states with min_age and max_age (years), as whole months, or null when they do not give a
 * clear span. Both ends are needed, and a value that is not a finite, non-negative number (commas included) is ignored.
 */
fun osmAgeSpan(minAge: String?, maxAge: String?): AgeSpan? {
    val from = yearsToMonths(minAge) ?: return null
    val to = yearsToMonths(maxAge) ?: return null
    if (from > to) return null
    return AgeSpan(from, to)
}

/** The trimmed value as whole months, or null when it is missing, not a number, NaN, infinite, or negative. */
private fun yearsToMonths(value: String?): Int? {
    val years = value?.trim()?.toDoubleOrNull() ?: return null
    if (years.isNaN() || years.isInfinite() || years < 0) return null
    return (years * 12).roundToInt()
}
