/**
 * The start screen: a search for the start and the destination, the children, the longest drive, a filter bar, and the
 * planned stops as text. While a plan is made, its route is passed to [onRoute] when it arrives and the share of the places
 * searched to [onProgress] (0 clears the line). A new plan is passed to [onPlanned]; the same route planned again with
 * another filter to [onRefiltered]; a tap on a stop's name passes the stop to [onStop]. The break button reads the position
 * once, in the page, and passes the break stops to [onPause] (an empty list clears them). Nothing is stored or sent.
 * [render] sets every text in a language and keeps what was typed. With [demo], the trip is the saved Stockholm to Göteborg
 * demo: its route, its places and its search come from the saved files, and no request is sent. With [saved], a plan whose
 * live places query failed may use the saved places on that route, and the notice says so. The demo button fills in that
 * demo trip and plans it from the saved data; the screen stays in demo mode until the page is reloaded or the start or
 * the destination is edited.
 */
class StartScreen(
    private val onRoute: (Route) -> Unit,
    private val onProgress: (share: Double) -> Unit,
    private val onPlanned: (Route, List<Stop>) -> Unit,
    private val onRefiltered: (Route, List<Stop>) -> Unit,
    private val onPause: (List<Stop>) -> Unit,
    private val onStop: (Stop) -> Unit,
    private val demo: SavedDemoLoader? = null,
    private val saved: SavedDemoLoader? = null,
) {
    val element = el("section")

    private var lang: Lang = Lang.En
    private var form = StartForm()
    /** The keys shown after the last press of the plan button. */
    private var errors: List<String> = emptyList()
    private var spanError = false
    private var planning = false
    /** The places queries answered and in all, once the route of the plan is known. */
    private var searched: Pair<Int, Int>? = null
    private var failure: String? = null
    private var stops: List<Stop>? = null
    private var filter = StopFilter()
    /** The route, places and family of the last plan, so a filter re-plans without new requests. */
    private var fetched: Fetched? = null
    /** The text key of the break result when it is a message, else its stops. */
    private var pauseKey: String? = null
    private var pauseStops: List<Stop> = emptyList()
    private var pauseRequest = 0
    /** The note on the saved data in use, empty when none is. */
    private val notice = el("p")
    private var demoData: SavedDemoData? = null
    /** The saved data of the demo: [demo] or else [saved], null when there is none. */
    private val demoLoader = demo ?: saved
    /** Whether the trip is the demo: with [demo], or once the demo button is pressed. */
    private var demoActive = demo != null
    /** The source of the saved places that stand in for the live ones in the last plan, null when the live ones are used. */
    private var fallback: Source? = null

    private class Fetched(val route: Route, val places: List<Place>, val family: Family)

    /** Sets one text in the language given to [render]. */
    private val updates = mutableListOf<(Lang) -> Unit>()
    /** Each message box with the keys it shows from [errors]. */
    private val errorBoxes = mutableListOf<Pair<HTMLElement, Set<String>>>()
    private val presetButtons = mutableListOf<Pair<Int, HTMLButtonElement>>()
    private val groupButtons = mutableListOf<Pair<AgeGroup, HTMLButtonElement>>()
    private val filterButtons = mutableListOf<Pair<() -> Boolean, HTMLButtonElement>>()
    /** The place fields, the start first, and their results, in the same order. */
    private val searchInputs = mutableListOf<HTMLInputElement>()
    private val searchResults = mutableListOf<HTMLElement>()
    private val searchButtons = mutableListOf<HTMLButtonElement>()
    /** The number of the latest plan request; an answer to an older one is dropped. */
    private var request = 0
    private val driveInput = numberInput()
    private val chosen = el("ul")
    private val planButton = button { plan() }
    private val status = el("p")
    private val stopList = el("ol")
    private val pauseButton = bound(button { pause() }, key("pause.now"))
    private val pauseStatus = el("p")
    private val pauseList = el("ol")
    private val pauseHeading = bound(el("h2"), key("pause.title"))
    private val tryDemoButton = bound(button { tryDemo() }, key("demo.try"))

    init {
        notice.id = "notice"
        element.appendChild(notice)
        if (demoLoader != null) {
            tryDemoButton.id = "try-demo"
            element.appendChild(tryDemoButton)
        }
        element.appendChild(
            searchField(key("start.field.start"), setOf("start.error.start")) { found ->
                form = form.copy(start = found)
                render(lang)
            },
        )
        element.appendChild(
            searchField(key("start.field.destination"), setOf("start.error.destination", "start.error.same")) { found ->
                form = form.copy(destination = found)
                render(lang)
            },
        )
        searchInputs[0].id = "start-input"
        searchButtons[0].id = "start-search"
        searchResults[0].id = "start-results"
        searchInputs[1].id = "destination-input"
        searchButtons[1].id = "destination-search"
        searchResults[1].id = "destination-results"
        element.appendChild(childrenSection())
        element.appendChild(driveSection())
        planButton.id = "plan"
        element.appendChild(planButton)
        element.appendChild(filterBar())
        status.id = "status"
        status.setAttribute("role", "status")
        status.setAttribute("aria-live", "polite")
        element.appendChild(status)
        element.appendChild(pauseButton)
        stopList.id = "stops"
        element.appendChild(stopList)
        element.appendChild(pauseHeading)
        element.appendChild(pauseStatus)
        element.appendChild(pauseList)
        if (demoActive) loadDemo()
    }

    /** Loads the saved demo data into the notice and the screen; a failed load shows its error. */
    private fun loadDemo() {
        val loader = demoLoader ?: return
        loader.load()
            .then { data ->
                demoData = data
                render(lang)
            }
            .catch { error ->
                failure = (error as? Throwable)?.message?.takeIf { it.startsWith("error.") } ?: "error.saved"
                render(lang)
            }
    }

    /** Leaves demo mode; the notice and the stops stay on screen until the next plan, because they are still demo data. */
    private fun leaveDemo() { demoActive = false }

    /** Fills in the demo trip, plans it from the saved data and keeps the screen in demo mode. */
    private fun tryDemo() {
        demoActive = true
        form = demoForm()
        filter = demoFilter()
        spanError = false
        driveInput.value = ""
        searchInputs[0].value = DEMO_START.name
        searchInputs[1].value = DEMO_DESTINATION.name
        for (results in searchResults) results.textContent = ""
        loadDemo()
        plan()
    }

    /** Shows the screen in [lang]: every text, the chosen children and drive, the errors and the stops. */
    fun render(lang: Lang) {
        this.lang = lang
        for (update in updates) update(lang)
        planButton.textContent = Messages.text(lang, if (planning) "start.planning" else "start.plan")
        planButton.disabled = planning
        for ((minutes, button) in presetButtons) {
            button.setAttribute("aria-pressed", (form.maxDriveMinutes == minutes).toString())
        }
        for ((group, button) in groupButtons) {
            button.setAttribute("aria-pressed", (Child.InSpan(AgeSpan.of(group)) in form.children).toString())
        }
        for ((isOn, button) in filterButtons) button.setAttribute("aria-pressed", isOn().toString())
        chosen.textContent = ""
        form.children.forEachIndexed { index, child -> chosen.appendChild(childItem(index, child)) }
        val shown = if (spanError) errors + "start.error.span" else errors
        for ((box, keys) in errorBoxes) {
            box.textContent = shown.filter { it in keys }.joinToString(" ") { Messages.text(lang, it) }
        }
        showStatus()
    }

    /** Toggle buttons for the age groups, the categories and the needs of the filter. */
    private fun filterBar(): HTMLElement {
        val section = el("section")
        section.appendChild(bound(el("h2"), key("filter.heading")))
        section.appendChild(filterGroup("filter.ages", AgeGroup.entries, { "ageGroup.${it.name}" }, { it in filter.ages }) {
            filter = filter.copy(ages = filter.ages.toggled(it))
        })
        section.appendChild(filterGroup("filter.categories", FILTER_CATEGORIES, { "category.${it.name}" }, { it in filter.categories }) {
            filter = filter.copy(categories = filter.categories.toggled(it))
        })
        section.appendChild(filterGroup("filter.needs", FILTER_NEEDS, { "need.${it.name}" }, { it in filter.needs }) {
            filter = filter.copy(needs = filter.needs.toggled(it))
        })
        return section
    }

    private fun <T> filterGroup(
        headingKey: String,
        items: List<T>,
        labelKey: (T) -> String,
        isOn: (T) -> Boolean,
        change: (T) -> Unit,
    ): HTMLElement {
        val group = el("div")
        group.appendChild(bound(el("strong"), key(headingKey)))
        for (item in items) {
            val toggle = bound(button { change(item); replan() }, key(labelKey(item)))
            markFilter(toggle, labelKey(item))
            filterButtons += { isOn(item) } to toggle
            group.appendChild(toggle)
        }
        return group
    }

    /** Gives the Play and Toilet filter buttons the ids that ci's look step clicks; the other filter buttons have none. */
    private fun markFilter(toggle: HTMLButtonElement, labelKey: String) {
        when (labelKey) {
            "category.Play" -> toggle.id = "filter-category-play"
            "need.Toilet" -> toggle.id = "filter-need-toilet"
        }
    }

    /** Gives the drive preset buttons the ids that ci's look step clicks. */
    private fun markDrive(preset: HTMLButtonElement, minutes: Int) {
        when (minutes) {
            30 -> preset.id = "drive-30"
            60 -> preset.id = "drive-60"
            90 -> preset.id = "drive-90"
            120 -> preset.id = "drive-120"
        }
    }

    private fun <T> Set<T>.toggled(item: T): Set<T> = if (item in this) this - item else this + item

    private fun childrenSection(): HTMLElement {
        val section = el("section")
        section.appendChild(bound(el("h2"), key("start.children.heading")))
        val groups = el("div")
        for (group in AgeGroup.entries) {
            val toggle = bound(button { toggleGroup(group) }, key("ageGroup.${group.name}"))
            groupButtons += group to toggle
            groups.appendChild(toggle)
        }
        section.appendChild(groups)
        section.appendChild(chosen)
        section.appendChild(errorBox(setOf("start.error.children")))
        section.appendChild(customRow())
        return section
    }

    /** The from and to of a custom age span in years and months, with the add button and its error. */
    private fun customRow(): HTMLElement {
        val fieldset = el("fieldset")
        fieldset.appendChild(bound(el("legend"), key("start.custom.heading")))
        val inputs = List(4) { numberInput() }
        fieldset.appendChild(bound(el("span"), key("start.custom.from")))
        fieldset.appendChild(labelled(key("unit.years"), inputs[0]))
        fieldset.appendChild(labelled(key("unit.months"), inputs[1]))
        fieldset.appendChild(bound(el("span"), key("start.custom.to")))
        fieldset.appendChild(labelled(key("unit.years"), inputs[2]))
        fieldset.appendChild(labelled(key("unit.months"), inputs[3]))
        fieldset.appendChild(bound(button { addCustom(inputs) }, key("start.custom.add")))
        fieldset.appendChild(errorBox(setOf("start.error.span")))
        return fieldset
    }

    private fun driveSection(): HTMLElement {
        val section = el("section")
        section.appendChild(bound(el("h2"), key("start.drive.heading")))
        val presets = el("div")
        for (minutes in DRIVE_PRESETS) {
            val preset = bound(button { chooseDrive(minutes) }) { lang -> formatMinutes(minutes, lang) }
            markDrive(preset, minutes)
            presetButtons += minutes to preset
            presets.appendChild(preset)
        }
        section.appendChild(presets)
        section.appendChild(labelled(key("start.drive.custom"), driveInput))
        driveInput.addEventListener("input", {
            form = form.copy(maxDriveMinutes = driveInput.value.toIntOrNull())
            render(lang)
        })
        section.appendChild(errorBox(setOf("start.error.drive")))
        return section
    }

    /** A place search: a field with its search button, and the results as buttons. Typing drops the pick made with [choose]. */
    private fun searchField(caption: (Lang) -> String, errorKeys: Set<String>, choose: (Found?) -> Unit): HTMLElement {
        val section = el("section")
        val searchForm = document.createElement("form") as HTMLFormElement
        val input = document.createElement("input") as HTMLInputElement
        input.type = "text"
        updates += { lang -> input.placeholder = Messages.text(lang, "search.label") }
        input.addEventListener("input", { leaveDemo(); choose(null) })
        val submit = document.createElement("button") as HTMLButtonElement
        submit.type = "submit"
        val results = el("div")
        searchInputs += input
        searchButtons += submit
        searchResults += results
        searchForm.appendChild(labelled(caption, input))
        searchForm.appendChild(bound(submit, key("search.button")))
        searchForm.appendChild(results)
        searchForm.addEventListener("submit", { event: Event ->
            event.preventDefault()
            if (input.value.isNotBlank()) {
                (if (demoActive) Promise.resolve(savedSearch(input.value)) else searchPlaces(input.value, lang))
                    .then { found ->
                        if (demoActive && found.isEmpty()) {
                            results.textContent = Messages.text(lang, "demo.search.none")
                        } else {
                            showResults(results, found, input, choose)
                        }
                    }
                    .catch { results.textContent = Messages.text(lang, failureKey("error.search", online())) }
            }
        })
        section.appendChild(searchForm)
        section.appendChild(errorBox(errorKeys))
        return section
    }

    private fun showResults(results: HTMLElement, found: List<Found>, input: HTMLInputElement, choose: (Found?) -> Unit) {
        results.textContent = ""
        for (place in found) {
            val item = button {
                input.value = place.name
                results.textContent = ""
                choose(place)
            }
            item.textContent = place.name
            results.appendChild(item)
        }
    }

    private fun addChild(child: Child) {
        form = form.copy(children = form.children + child)
        render(lang)
    }

    /** Removes one child of [group] when there is one, else adds one. */
    private fun toggleGroup(group: AgeGroup) {
        val child = Child.InSpan(AgeSpan.of(group))
        val index = form.children.lastIndexOf(child)
        if (index >= 0) removeChild(index) else addChild(child)
    }

    private fun removeChild(index: Int) {
        form = form.copy(children = form.children.filterIndexed { i, _ -> i != index })
        render(lang)
    }

    /** Adds the span of the four inputs (from years, from months, to years, to months); a blank counts as 0. */
    private fun addCustom(inputs: List<HTMLInputElement>) {
        val (fromYears, fromMonths, toYears, toMonths) = inputs.map { it.value.toIntOrNull() ?: 0 }
        val child = customChild(fromYears, fromMonths, toYears, toMonths)
        spanError = child == null
        if (child != null) {
            addChild(child)
            inputs.forEach { it.value = "" }
        } else {
            render(lang)
        }
    }

    private fun chooseDrive(minutes: Int) {
        form = form.copy(maxDriveMinutes = minutes)
        driveInput.value = ""
        render(lang)
    }

    private fun childItem(index: Int, child: Child): HTMLElement {
        val item = el("li")
        item.textContent = childLabel(child, lang) + " "
        val remove = button { removeChild(index) }
        remove.textContent = Messages.text(lang, "start.child.remove")
        item.appendChild(remove)
        return item
    }

    /** Checks the form and, when it is complete, fetches the route and the places and plans the stops. */
    private fun plan() {
        val current = ++request
        if (!demoActive) demoData = null
        errors = check(form)
        failure = null
        stops = null
        fetched = null
        searched = null
        fallback = null
        clearPause()
        planning = false
        val start = form.start
        val destination = form.destination
        if (errors.isEmpty() && start != null && destination != null) {
            if (demoActive && (start != DEMO_START || destination != DEMO_DESTINATION)) {
                failure = "error.demoTrip"
            } else {
                planning = true
                val family = family(form)
                val loader = demoLoader
                val fetching = if (demoActive && loader != null) {
                    loader.load().then { data ->
                        if (current == request) onRoute(data.route)
                        Fetched(data.route, data.places, family)
                    }
                } else {
                    fetchTrip(start, destination, current, family)
                }
                fetching
                    .then { result -> if (current == request) showStops(result) }
                    .catch { error -> if (current == request) fail(error) }
            }
        }
        render(lang)
    }

    /** The route from the server, then the places near it; the route goes to [onRoute] when it arrives. */
    private fun fetchTrip(start: Found, destination: Found, current: Int, family: Family): Promise<Fetched> {
        return fetchRoute(start.lat, start.lon, destination.lat, destination.lon)
            .then { route ->
                if (current == request) onRoute(route)
                val live = { fetchPlaces(route) { done, total -> if (current == request) searching(done, total) } }
                if (saved != null) {
                    placesOrSaved(route, live, saved).then { answer ->
                        if (current == request) fallback = answer.saved
                        Fetched(route, answer.places, family)
                    }
                } else {
                    live().then { places -> Fetched(route, places, family) }
                }
            }
            .then { trip -> trip } // Flattens the promise of a promise into one level.
    }

    /** Shows how many places queries have answered, in the text and on the map's progress line. */
    private fun searching(done: Int, total: Int) {
        searched = done to total
        onProgress(if (total == 0) 1.0 else done.toDouble() / total)
        render(lang)
    }

    private fun showStops(result: Fetched) {
        planning = false
        fetched = result
        val planned = StopPlanner.plan(result.route, result.places, result.family, filter = filter)
        stops = planned
        onPlanned(result.route, planned)
        render(lang)
    }

    /** Plans again from the route and places already fetched, with the current filter, and shows the result. */
    private fun replan() {
        val last = fetched
        if (last != null) {
            val planned = StopPlanner.plan(last.route, last.places, last.family, filter = filter)
            stops = planned
            clearPause()
            onRefiltered(last.route, planned)
        }
        render(lang)
    }

    private fun clearPause() {
        pauseRequest++
        pauseKey = null
        pauseStops = emptyList()
        onPause(emptyList())
    }

    /** Asks for the position once and shows the break stops near it; the position is used here and kept nowhere. */
    private fun pause() {
        val last = fetched ?: return
        val current = ++pauseRequest
        pauseKey = null
        pauseStops = emptyList()
        val geolocation = window.navigator.asDynamic().geolocation
        if (geolocation == null || jsTypeOf(geolocation) == "undefined") {
            showPause(current, "pause.noPosition", emptyList())
            return
        }
        val onPosition = { position: dynamic ->
            val coords = position.coords
            val result = pauseNow(
                last.route, last.places, last.family, filter, coords.latitude as Double, coords.longitude as Double,
            )
            when (result) {
                PauseResult.OffRoute -> showPause(current, "pause.offRoute", emptyList())
                is PauseResult.Stops ->
                    showPause(current, if (result.stops.isEmpty()) "pause.none" else null, result.stops)
            }
        }
        val onFailure = { _: dynamic -> showPause(current, "pause.noPosition", emptyList()) }
        try {
            geolocation.getCurrentPosition(onPosition, onFailure)
        } catch (e: Throwable) {
            showPause(current, "pause.noPosition", emptyList())
        }
    }

    private fun showPause(current: Int, messageKey: String?, found: List<Stop>) {
        if (current != pauseRequest) return
        pauseKey = messageKey
        pauseStops = found
        onPause(found)
        render(lang)
    }

    private fun fail(error: Any?) {
        planning = false
        searched = null
        onProgress(0.0)
        val key = (error as? Throwable)?.message?.takeIf { it.startsWith("error.") } ?: "error.route"
        failure = failureKey(key, online())
        render(lang)
    }

    /** Whether the device is online; only a false answer is trusted, so an unknown state counts as online. */
    private fun online(): Boolean = window.navigator.asDynamic().onLine != false

    /** The current step of a plan: the route, then the places searched so far, then the choice of stops. */
    private fun planningText(): String {
        val (done, total) = searched ?: return Messages.text(lang, "start.planning.route")
        return if (done < total) {
            Messages.text(lang, "start.planning.places", mapOf("done" to done, "total" to total))
        } else {
            Messages.text(lang, "start.planning.stops")
        }
    }

    private fun showStatus() {
        val noticeText = demoData?.let { demoNotice(lang, it) } ?: fallback?.let { savedNotice(lang, it) } ?: ""
        notice.textContent = noticeText
        notice.hidden = noticeText.isEmpty()
        val failed = failure
        val planned = stops
        val last = fetched
        val gaps = if (planned != null && planned.isNotEmpty() && last != null) {
            uncoveredStretches(last.route.totalSeconds, planned.map { it.routeSeconds }, last.family.maxDriveMinutes)
        } else {
            emptyList()
        }
        val filterActive = filter != StopFilter()
        status.textContent = when {
            planning -> planningText()
            failed != null -> Messages.text(lang, failed)
            planned != null && planned.isEmpty() -> Messages.text(lang, "start.noStops")
            else -> gapNotice(lang, gaps, filterActive) ?: ""
        }
        status.classList.toggle("busy", planning)
        stopList.textContent = ""
        for (stop in planned.orEmpty()) stopList.appendChild(stopItem(stop))
        val pauseShown = fetched != null
        pauseButton.hidden = !pauseShown
        pauseHeading.hidden = !pauseShown || (pauseKey == null && pauseStops.isEmpty())
        pauseStatus.textContent = pauseKey?.let { Messages.text(lang, it) } ?: ""
        pauseList.textContent = ""
        for (stop in pauseStops) pauseList.appendChild(stopItem(stop))
    }

    /** A stop: its name, which opens its card, its time from the start, its detour and why it fits the family. */
    private fun stopItem(stop: Stop): HTMLElement {
        val item = el("li")
        val name = button { onStop(stop) }
        name.textContent = placeLabel(stop.place.name, stop.place.categories, lang)
        item.appendChild(name)
        val lines = listOf(
            Messages.text(lang, "stop.time", mapOf("time" to formatMinutes(stop.routeSeconds / 60, lang))),
            Messages.text(lang, "stop.detour", mapOf("minutes" to stop.detourMinutes)),
            explain(stop.match, lang),
        )
        for (line in lines) item.appendChild(el("div").apply { textContent = line })
        return item
    }

    /** Keeps [element]'s text in the language that [render] sets. */
    private fun <T : HTMLElement> bound(element: T, text: (Lang) -> String): T {
        updates += { lang -> element.textContent = text(lang) }
        return element
    }

    private fun key(key: String): (Lang) -> String = { lang -> Messages.text(lang, key) }

    private fun errorBox(keys: Set<String>): HTMLElement {
        val box = el("p")
        box.classList.add("error")
        errorBoxes += box to keys
        return box
    }

    /** A caption with its control inside one label. */
    private fun labelled(caption: (Lang) -> String, control: HTMLElement): HTMLElement {
        val label = el("label")
        label.appendChild(bound(el("span"), caption))
        label.appendChild(control)
        return label
    }

    private fun button(onClick: () -> Unit): HTMLButtonElement {
        val button = document.createElement("button") as HTMLButtonElement
        button.type = "button"
        button.addEventListener("click", { onClick() })
        return button
    }

    private fun numberInput(): HTMLInputElement {
        val input = document.createElement("input") as HTMLInputElement
        input.type = "number"
        input.min = "0"
        return input
    }

    private fun el(tag: String): HTMLElement = document.createElement(tag) as HTMLElement
}

