package trip.plan

import trip.AgeGroup
import trip.AgeSpan
import trip.Need
import trip.match.placeAgeFit
import trip.place.Category

/** What the family narrows the stops to; an empty set means no limit. Categories and ages match any, needs must all hold. */
data class StopFilter(
    val ages: Set<AgeGroup> = emptySet(),
    val categories: Set<Category> = emptySet(),
    val needs: Set<Need> = emptySet(),
)

/**
 * Whether [stop] passes. A need passes only when it is known to be true on the place. An age group passes when the match
 * has a positive age reason for it, or when the age fit of the place overlaps it: the age the place states itself first,
 * then the age derived from the play equipment.
 */
fun StopFilter.accepts(stop: Stop): Boolean {
    val place = stop.place
    if (categories.isNotEmpty() && categories.none { it in place.categories }) return false
    if (needs.any { place.needs[it]?.value != true }) return false
    return ages.isEmpty() || ages.any { fitsAge(stop, it) }
}

private fun fitsAge(stop: Stop, group: AgeGroup): Boolean {
    val reasoned = stop.match.reasons.any { reason ->
        reason.positive && reason.key == "match.age.fits" && (reason.params["groups"] as? List<*>)?.contains(group.name) == true
    }
    if (reasoned) return true
    val span = placeAgeFit(stop.place)?.span
    return span != null && span.overlaps(AgeSpan.of(group))
}

/** The stops that pass [filter], in the order given. */
fun filtered(stops: List<Stop>, filter: StopFilter): List<Stop> = stops.filter { filter.accepts(it) }
