package trip.match

import trip.AgeSpan
import trip.place.Place

/** Where an age fit came from: derived from tags, or from users. Only [Tags] is used so far; [Users] is for later ratings. */
enum class FitSource { Tags, Users }

/** How sure we are of an age fit. Only [Low] is used so far; [Medium] and [High] are for when users confirm a fit. */
enum class Confidence { Low, Medium, High }

/** The ages a place suits, with where that fit came from, how confident we are in it, and whether the place states the age itself ([stated]) or it is worked out from equipment. */
data class AgeFit(val span: AgeSpan, val source: FitSource, val confidence: Confidence, val stated: Boolean = false)

/**
 * The age fit read from equipment tags, or null when no equipment is known. An age fit from tags is derived from
 * equipment and is the weakest source, so its confidence is always Low until users confirm it (provisional rule; the CD may change it).
 */
fun tagAgeFit(equipment: List<String>): AgeFit? {
    val span = EquipmentAges.spanFor(equipment) ?: return null
    return AgeFit(span, FitSource.Tags, Confidence.Low)
}

/** The age fit for [place]: the age it states itself (Medium), else the one worked out from its equipment (Low), else null. */
fun placeAgeFit(place: Place): AgeFit? {
    val stated = place.statedAge
    if (stated != null) return AgeFit(stated.value, FitSource.Tags, Confidence.Medium, stated = true)
    return tagAgeFit(place.equipment)
}
