package trip.web

import kotlinx.browser.document
import org.w3c.dom.HTMLButtonElement
import org.w3c.dom.HTMLElement
import trip.i18n.Lang
import trip.i18n.Messages
import trip.match.explain
import trip.place.placeLabel
import trip.plan.Stop
import trip.stop.card
import trip.stop.lines
import trip.stop.sourceLines

/**
 * The stop card under the map and the trip: the open stop's card with its add button, then the stops added, in route
 * order, with a remove button. Nothing is stored. [render] redraws both in a language and keeps the open card.
 */
class StopPanel {
    val element = el("section")

    private var lang: Lang = Lang.En
    private var shown: Stop? = null
    private val trip = mutableListOf<Stop>()

    /** Called with the stop whose card is open, or null when the card is closed or reset. */
    var onShown: (Stop?) -> Unit = {}

    /** Opens the card of [stop] and scrolls it into view. */
    fun show(stop: Stop) {
        shown = stop
        onShown(stop)
        render(lang)
        element.querySelector("#stop-card")?.scrollIntoView()
    }

    /** Closes the card and empties the trip, for a new plan. */
    fun reset() {
        shown = null
        onShown(null)
        trip.clear()
        render(lang)
    }

    /** Shows the card and the trip in [lang]. */
    fun render(lang: Lang) {
        this.lang = lang
        element.textContent = ""
        shown?.let { element.appendChild(cardSection(it)) }
        element.appendChild(tripSection())
    }

    private fun cardSection(stop: Stop): HTMLElement {
        val section = el("section")
        section.id = "stop-card"
        val stopCard = card(stop)
        val heading = el("h2")
        heading.textContent = placeLabel(stop.place.name, stop.place.categories, lang)
        section.appendChild(heading)
        section.appendChild(paragraph(explain(stopCard.match, lang)))
        for (line in lines(stopCard, lang)) {
            val text = listOfNotNull(line.value.takeIf { it.isNotEmpty() }, line.note?.let { "($it)" }).joinToString(" ")
            section.appendChild(paragraph("${line.label}: $text"))
        }
        for (line in sourceLines(stopCard, lang)) {
            section.appendChild(paragraph(line).apply { className = "card-source" })
        }
        if (stop in trip) {
            section.appendChild(paragraph(Messages.text(lang, "trip.added")))
        } else {
            section.appendChild(textButton("trip.add") {
                trip += stop
                render(lang)
            }.also { it.id = "trip-add" })
        }
        section.appendChild(textButton("card.close") {
            shown = null
            onShown(null)
            render(lang)
        })
        return section
    }

    private fun tripSection(): HTMLElement {
        val section = el("section")
        val heading = el("h2")
        heading.textContent = Messages.text(lang, "trip.title")
        section.appendChild(heading)
        val list = el("ol")
        list.id = "trip-list"
        for (stop in trip.sortedBy { it.routeSeconds }) {
            val item = el("li")
            item.textContent = placeLabel(stop.place.name, stop.place.categories, lang) + " "
            item.appendChild(textButton("trip.remove") {
                trip -= stop
                render(lang)
            })
            list.appendChild(item)
        }
        section.appendChild(list)
        return section
    }

    private fun paragraph(text: String): HTMLElement = el("p").apply { textContent = text }

    private fun textButton(key: String, onClick: () -> Unit): HTMLButtonElement {
        val button = document.createElement("button") as HTMLButtonElement
        button.type = "button"
        button.textContent = Messages.text(lang, key)
        button.addEventListener("click", { onClick() })
        return button
    }

    private fun el(tag: String): HTMLElement = document.createElement(tag) as HTMLElement
}
