package trip.match

import trip.AgeSpan

/**
 * The ages each kind of playground equipment suits. OpenStreetMap tags age on 31 of 20,895 playgrounds, so a
 * playground's age fit is derived from its equipment. Unknown names are ignored.
 */
object EquipmentAges {
    private val table = mapOf(
        "baby_swing" to AgeSpan(6, 36),
        "sandpit" to AgeSpan(12, 72),
        "swing" to AgeSpan(24, 192),
        "slide" to AgeSpan(24, 144),
        "springy" to AgeSpan(18, 84),
        "climbingframe" to AgeSpan(48, 156),
        "zipwire" to AgeSpan(72, 192),
        "basketswing" to AgeSpan(12, 144),
        "seesaw" to AgeSpan(36, 120),
        "playhouse" to AgeSpan(18, 84),
    )

    /** The equipment names this table knows, in the order given. */
    fun known(equipment: List<String>): List<String> = equipment.filter { table.containsKey(it) }

    /** The union of the known items' spans, or null when none is known. */
    fun spanFor(equipment: List<String>): AgeSpan? {
        val spans = known(equipment).map { table.getValue(it) }
        if (spans.isEmpty()) return null
        return AgeSpan(spans.minOf { it.fromMonths }, spans.maxOf { it.toMonths })
    }
}
