package trip.i18n

/** The app's interface languages. Both exist from the start and every screen supports both (owner, 2026-10-23). */
enum class Lang(val tag: String) {
    En("en"),
    Sv("sv");

    companion object {
        /** The language for a platform language tag such as "sv-SE" or "en-US": Swedish for "sv*", else English. */
        fun fromTag(tag: String?): Lang = if (tag?.lowercase()?.startsWith("sv") == true) Sv else En
    }
}

