    fun table(lang: Lang): Map<String, String> = when (lang) {
        Lang.En -> en
        Lang.Sv -> sv
    }

    /** The text for [key] in [lang] with `{name}` placeholders filled from [params]; throws on an unknown key. */
    fun text(lang: Lang, key: String, params: Map<String, Any> = emptyMap()): String {
        val template = requireNotNull(table(lang)[key]) { "No text for key $key" }
        return Regex("\\{(\\w+)\\}").replace(template) { m -> params[m.groupValues[1]]?.toString() ?: m.value }
    }
