package trip.place

/** The equipment-only place for a `playground=*` node such as a swing, or null when the element is not one. */
fun equipmentPlace(e: OsmElement): Place? {
    if (e.tags["leisure"] == "playground") return null
    val names = e.tags["playground"]?.split(';')?.map { it.trim() }?.filter { it.isNotEmpty() }?.distinct()?.sorted()
    if (names.isNullOrEmpty()) return null
    return Place(
        osmId = "${e.type}/${e.id}",
        name = null,
        lat = e.lat,
        lon = e.lon,
        categories = emptySet(),
        needs = emptyMap(),
        openingHours = null,
        fee = null,
        equipment = names,
    )
}

/** True for a place that is only equipment from a `playground=*` node: no category, some equipment. */
fun isEquipmentOnly(place: Place): Boolean = place.categories.isEmpty() && place.equipment.isNotEmpty()

/**
 * Folds each equipment-only place into the nearest play place within [metres] of it, adding its equipment to that place.
 * Equipment-only places are removed from the result, whether they were merged or not.
 */
fun mergeEquipment(places: List<Place>, metres: Double = 50.0): List<Place> {
    val result = places.filterNot { isEquipmentOnly(it) }.toMutableList()
    for (node in places.filter { isEquipmentOnly(it) }) {
        val index = result.indices
            .filter { Category.Play in result[it].categories && distanceMetres(result[it].lat, result[it].lon, node.lat, node.lon) <= metres }
            .minWithOrNull(
                compareBy<Int> { distanceMetres(result[it].lat, result[it].lon, node.lat, node.lon) }.thenBy { result[it].osmId },
            )
        if (index != null) {
            val place = result[index]
            result[index] = place.copy(equipment = (place.equipment + node.equipment).distinct().sorted())
        }
    }
    return result
}
