package trip.net

import trip.place.Place
import trip.place.Source
import trip.place.placeOrToilet

/**
 * The places of one live Overpass answer given as JSON [text]: elements without a position or a category are left out,
 * except public toilets. Toilets are not merged here, because the app combines the answers of all queries afterwards.
 * An answer whose remark reports a runtime error throws IllegalArgumentException with the message key
 * `error.placesIncomplete`; any other failure throws IllegalArgumentException with the key `error.places`.
 */
fun livePlaces(text: String, source: Source): List<Place> {
    val parsed = try {
        parseJson(text)
    } catch (e: IllegalArgumentException) {
        throw IllegalArgumentException("error.places", e)
    }
    if (parsed is Map<*, *> && overpassIncomplete(parsed["remark"] as? String)) {
        throw IllegalArgumentException("error.placesIncomplete")
    }
    return try {
        savedElements(parsed).mapNotNull { placeOrToilet(it, source) }
    } catch (e: IllegalArgumentException) {
        throw IllegalArgumentException("error.places", e)
    }
}
