package trip.start

import trip.i18n.Lang
import trip.i18n.Messages
import trip.plan.Stretch

/**
 * The notice for the stretches of a trip with no stop in reach, or null when there are none. It names the first stretch
 * and counts the others; [filterActive] picks the text that suggests removing a filter.
 */
fun gapNotice(lang: Lang, stretches: List<Stretch>, filterActive: Boolean): String? {
    val first = stretches.firstOrNull() ?: return null
    val key = if (filterActive) "start.gap" else "start.gap.noFilter"
    val more = if (stretches.size == 1) "" else Messages.text(lang, "start.gap.more", mapOf("count" to stretches.size - 1))
    return Messages.text(
        lang,
        key,
        mapOf(
            "from" to formatMinutes(first.fromSeconds / 60, lang),
            "to" to formatMinutes(first.toSeconds / 60, lang),
            "more" to more,
        ),
    )
}
