package trip.plan

import trip.place.distanceMetres
import kotlin.math.abs

private const val SEED_STEP = 32

/** One degree of latitude is at least 111,195 m on the sphere, so this is a safe lower bound on distance per degree. */
private const val METRES_PER_DEGREE_BOUND = 111_000.0

/** A point on the route and the seconds from the start of the trip to reach it. */
data class RoutePoint(val lat: Double, val lon: Double, val seconds: Int)

/** The route as points in time order: at least two, with [RoutePoint.seconds] rising. */
data class Route(val points: List<RoutePoint>) {
    init {
        require(points.size >= 2) { "A route has at least two points, was ${points.size}" }
        require(points.zipWithNext().all { (a, b) -> b.seconds > a.seconds }) { "Route points must rise in time" }
    }

    val totalSeconds: Int get() = points.last().seconds

    /**
     * The index of the route point nearest to ([lat], [lon]), and its distance in metres.
     * On equal distances the lowest index wins. Points whose latitude alone is further away than the
     * best distance so far cannot be nearer, so they are skipped without the haversine formula.
     */
    fun nearest(lat: Double, lon: Double): Pair<Int, Double> {
        var index = 0
        var best = Double.MAX_VALUE
        fun consider(i: Int) {
            val distance = distanceMetres(lat, lon, points[i].lat, points[i].lon)
            if (distance < best || (distance == best && i < index)) {
                index = i
                best = distance
            }
        }
        for (i in points.indices step SEED_STEP) consider(i)
        consider(points.lastIndex)
        points.indices.forEach { i ->
            if (abs(lat - points[i].lat) * METRES_PER_DEGREE_BOUND > best) return@forEach
            consider(i)
        }
        return index to best
    }
}
