package trip.net

import trip.i18n.Lang
import trip.i18n.Messages

/**
 * The plain on-screen notice that demo mode runs on saved data, with the date of the route and of the places.
 * The source names are fixed words in the messages; the saved header's long name is not shown.
 */
fun demoNotice(lang: Lang, data: SavedDemoData): String =
    Messages.text(
        lang,
        "demo.notice",
        mapOf(
            "routeDate" to data.routeSource.date,
            "placesDate" to data.placesSource.date,
        ),
    )
