package trip.match

import trip.AgeSpan
import trip.Family
import trip.Interest
import trip.i18n.Lang
import trip.i18n.Messages
import trip.place.Category
import trip.place.Place
import kotlin.math.roundToInt

/** One reason behind a score: a [Messages] key with its parameters, and whether it counts for the family. */
data class Reason(val key: String, val params: Map<String, Any> = emptyMap(), val positive: Boolean)

/**
 * How well a place fits a family: [percent] in 0..100, and at most four [reasons], positive ones first.
 * [ageFit] is the age fit the score used, or null when the place is not a playground or has no known equipment,
 * and no stated age either.
 * [detourPoints] is what a detour took off [percent], and [detourMinutes] is that detour's minutes; both are 0 when no
 * detour was taken off the score.
 */
data class Match(
    val percent: Int,
    val reasons: List<Reason>,
    val ageFit: AgeFit? = null,
    val detourPoints: Int = 0,
    val detourMinutes: Int = 0,
) {
    init {
        require(detourPoints >= 0) { "detourPoints must not be negative: $detourPoints" }
        require(detourMinutes >= 0) { "detourMinutes must not be negative: $detourMinutes" }
    }
}

/** Family Match: age 50 points, needs 30, interests 20. Model-free and deterministic. */
object FamilyMatch {
    private const val AGE_POINTS = 50.0
    private const val NEED_POINTS = 30.0
    private const val INTEREST_POINTS = 20.0
    private const val MAX_REASONS = 4
    private val allAges = AgeSpan(0, Int.MAX_VALUE)

    fun score(place: Place, family: Family): Match {
        val reasons = mutableListOf<Reason>()
        val (agePoints, ageFit) = ageScore(place, family, reasons)
        val points = agePoints + needScore(place, family, reasons) + interestScore(place, family, reasons)
        val shown = reasons.sortedBy { !it.positive }.take(MAX_REASONS)
        return Match(points.roundToInt().coerceIn(0, 100), shown, ageFit)
    }

    /** Playgrounds suit the ages of their equipment, and a place with a stated age suits those ages; other places are assumed to suit all ages. Returns the points and the fit used. */
    private fun ageScore(place: Place, family: Family, reasons: MutableList<Reason>): Pair<Double, AgeFit?> {
        val playground = Category.Play in place.categories
        val fit = if (playground || place.statedAge != null) placeAgeFit(place) else null
        if (playground && fit == null) {
            reasons += Reason("match.age.unknown", positive = false)
            return AGE_POINTS / 2 to null
        }
        val span = fit?.span ?: allAges
        if (family.children.any { it.span().overlaps(span) }) {
            val fitting = family.children.map { it.span() }.filter { it.overlaps(span) }
            val groups = family.groups().filter { group -> fitting.any { it.overlaps(AgeSpan.of(group)) } }.map { it.name }
            reasons += Reason("match.age.fits", mapOf("groups" to groups), positive = true)
        }
        if (fit != null && fit.stated) {
            reasons += Reason("match.age.stated", mapOf("confidence" to fit.confidence.name), positive = true)
        } else if (fit != null) {
            val params = mapOf("equipment" to EquipmentAges.known(place.equipment).joinToString(), "confidence" to fit.confidence.name)
            reasons += Reason("match.age.derived", params, positive = true)
        }
        if (family.children.any { it.span().toMonths < span.fromMonths }) reasons += Reason("match.age.tooYoung", positive = false)
        if (family.children.any { it.span().fromMonths > span.toMonths }) reasons += Reason("match.age.tooOld", positive = false)
        return AGE_POINTS * family.children.count { it.span().overlaps(span) } / family.children.size to fit
    }

    /** Each need the family has is worth an equal share: true scores it, false scores nothing, unknown a third of it. */
    private fun needScore(place: Place, family: Family, reasons: MutableList<Reason>): Double {
        if (family.needs.isEmpty()) return NEED_POINTS
        val share = NEED_POINTS / family.needs.size
        return family.needs.sorted().sumOf { need ->
            val params = mapOf("need" to need.name)
            when (place.needs[need]?.value) {
                true -> {
                    reasons += Reason("match.need.has", params, positive = true)
                    share
                }
                false -> {
                    reasons += Reason("match.need.missing", params, positive = false)
                    0.0
                }
                null -> {
                    reasons += Reason("match.need.unknown", params, positive = false)
                    share / 3
                }
            }
        }
    }

    /** The share of the family's interests that the place covers. */
    private fun interestScore(place: Place, family: Family, reasons: MutableList<Reason>): Double {
        if (family.interests.isEmpty()) return INTEREST_POINTS / 2
        var covered = 0
        for (interest in family.interests.sorted()) {
            if (categoriesFor(interest).any { it in place.categories }) {
                covered++
                reasons += Reason("match.interest", mapOf("interest" to interest.name), positive = true)
            }
        }
        return INTEREST_POINTS * covered / family.interests.size
    }

    /** The place categories that cover an interest. Dinosaurs and Trains have no place category yet. */
    private fun categoriesFor(interest: Interest): Set<Category> = when (interest) {
        Interest.Animals -> setOf(Category.Animals)
        Interest.Swimming -> setOf(Category.Swimming)
        Interest.Nature -> setOf(Category.Nature)
        Interest.History, Interest.Science -> setOf(Category.Museum)
        Interest.Adventure, Interest.Sport -> setOf(Category.Play)
        Interest.Dinosaurs, Interest.Trains -> emptySet()
    }
}

/**
 * The match as one sentence in [lang]: the headline, then the reasons joined with the language's separators, then the
 * detour deduction if there is one.
 */
fun explain(match: Match, lang: Lang): String {
    val headline = Messages.text(lang, "match.headline", mapOf("percent" to match.percent))
    val detour = if (match.detourPoints == 0) "" else {
        val text = Messages.text(lang, "match.detour", mapOf("points" to match.detourPoints, "minutes" to match.detourMinutes))
        if (match.reasons.isEmpty()) text else Messages.text(lang, "match.separator") + " " + text
    }
    return "$headline ${joinList(match.reasons.map { render(it, lang) }, lang)}$detour."
}

/** The reason's text, with group, need and interest names replaced by their labels in [lang]. */
private fun render(reason: Reason, lang: Lang): String {
    val params = reason.params.mapValues { (name, value) ->
        when (name) {
            "groups" -> joinList((value as List<*>).map { Messages.text(lang, "ageGroup.$it") }, lang)
            "need" -> Messages.text(lang, "need.$value")
            "interest" -> Messages.text(lang, "interest.$value")
            "confidence" -> Messages.text(lang, "confidence.$value")
            else -> value
        }
    }
    return Messages.text(lang, reason.key, params)
}

private fun joinList(items: List<String>, lang: Lang): String {
    if (items.size < 2) return items.joinToString()
    val separator = Messages.text(lang, "match.separator")
    val last = Messages.text(lang, "match.lastSeparator")
    return items.dropLast(1).joinToString("$separator ") + " $last " + items.last()
}
