package trip.net

import trip.place.Source

/** A saved file's source and date header, with the raw answer found under the requested key. */
data class SavedFile(val source: Source, val answer: Any?)

/** Reads the text of a saved file: its header must be valid and [key] must be present; throws IllegalArgumentException otherwise. */
fun readSavedFile(text: String, key: String): SavedFile {
    val map = parseJson(text) as? Map<*, *> ?: throw IllegalArgumentException("Saved file is not an object")
    val source = savedSource(map["source"] as? String, map["date"] as? String)
        ?: throw IllegalArgumentException("Saved file has no valid source and date")
    if (!map.containsKey(key)) throw IllegalArgumentException("Saved file has no \"$key\" answer")
    return SavedFile(source, map[key])
}
