package trip.net

import trip.place.Place
import trip.place.Source
import trip.plan.Route

/** The route and places of the saved Stockholm to Göteborg demo, each with the source named in its file's header. */
data class SavedDemoData(val route: Route, val routeSource: Source, val places: List<Place>, val placesSource: Source)

/** Reads the texts of the saved route and places files into the demo data; throws IllegalArgumentException if either is bad. */
fun savedDemoData(routeText: String, placesText: String): SavedDemoData {
    val routeFile = readSavedFile(routeText, "osrm")
    val route = savedRoute(routeFile.answer)
    require(fitsSavedDemoRoute(route)) { "Saved route does not run between Stockholm and Göteborg" }
    val placesFile = readSavedFile(placesText, "overpass")
    return SavedDemoData(route, routeFile.source, savedPlaces(placesFile.answer, placesFile.source), placesFile.source)
}
