package trip.net

import trip.i18n.Lang

/** OpenStreetMap's search service, Nominatim: the search host the app uses (see AGENTS.md). */
private const val NOMINATIM_SEARCH = "https://nominatim.openstreetmap.org/search"

/** Characters that stay as they are in a percent-encoded query, besides letters and digits. */
private const val UNRESERVED = "-._~"

/** A place from a search: its [name] and its position in degrees. */
data class Found(val name: String, val lat: Double, val lon: Double)

/**
 * The URL of the search for [text] in Sweden, Norway, Denmark and Finland, with at most five places as JSON in [lang].
 * Blank text is refused.
 */
fun searchUrl(text: String, lang: Lang): String {
    require(text.isNotBlank()) { "A search needs some text" }
    return "$NOMINATIM_SEARCH?format=jsonv2&limit=5&countrycodes=se,no,dk,fi&accept-language=${lang.tag}" +
        "&q=${percentEncode(text)}"
}

/**
 * The place with [displayName] at [lat] and [lon] (Nominatim's strings), or null when a coordinate is not a finite
 * number. The name is the display name up to its second comma, so "Liseberg, Göteborg, Sverige" becomes "Liseberg, Göteborg".
 */
fun found(displayName: String, lat: String, lon: String): Found? {
    val latitude = lat.toDoubleOrNull()?.takeIf { it.isFinite() } ?: return null
    val longitude = lon.toDoubleOrNull()?.takeIf { it.isFinite() } ?: return null
    return Found(displayName.split(",").take(2).joinToString(","), latitude, longitude)
}

/** [text] as UTF-8 bytes, each byte outside the unreserved characters written as `%XX`; a space becomes `%20`. */
internal fun percentEncode(text: String): String = buildString {
    for (byte in text.encodeToByteArray()) {
        val code = byte.toInt() and 0xFF
        val c = code.toChar()
        if (c in 'A'..'Z' || c in 'a'..'z' || c in '0'..'9' || c in UNRESERVED) {
            append(c)
        } else {
            append('%').append(code.toString(16).uppercase().padStart(2, '0'))
        }
    }
}
