package trip.web

import kotlinx.browser.document
import org.w3c.dom.Element
import org.w3c.dom.HTMLButtonElement
import trip.i18n.Lang
import trip.i18n.Messages
import trip.plan.PROGRESS_LAYER
import trip.plan.ROUTE_LAYER
import trip.plan.Route
import trip.plan.RoutePoint
import trip.plan.Stop
import trip.plan.routeLayerOrder
import trip.plan.routeUpTo

// The route as a muted line, the part searched so far over it, and each stop as a numbered marker. A change made before the
// style has loaded is made on load.

private const val MUTED_LINE = "#94a3b8"
private const val ACCENT_LINE = "#1d4ed8"

/**
 * The map of the latest plan: the route, the part of it searched so far, and one numbered marker per stop in route order.
 * A tap on a marker calls [onStop].
 */
class RouteMap(private val map: MapLibreMap, private val onStop: (Stop) -> Unit) {
    private var lang: Lang = Lang.En
    private var loaded = false
    /** The changes made before the style loaded, in order; they are made on load. */
    private val waiting = mutableListOf<() -> Unit>()
    /** The route of the latest plan, which the progress line runs along. */
    private var plannedRoute: Route? = null
    private val markers = mutableListOf<Marker>()
    private val pauseMarkers = mutableListOf<Marker>()
    /** The OSM id of the stop whose markers are marked as selected, or null for none. */
    private var selectedId: String? = null

    init {
        map.on("load") {
            loaded = true
            addLines()
            waiting.forEach { it() }
            waiting.clear()
        }
    }

    /** Shows [route] as the muted line and fits the view to it; the last plan's stops and the progress line are removed. */
    fun showRoute(route: Route) = whenLoaded { drawRoute(route) }

    /** Draws the part of the route searched so far in the accent colour over the muted line; a share of 0 removes it. */
    fun showProgress(share: Double) = whenLoaded {
        val points = plannedRoute?.let { routeUpTo(it, share) }.orEmpty()
        setLine(PROGRESS_LAYER, points)
    }

    /** Shows [route] and [stops] in place of the last plan's; the progress line is removed. */
    fun show(route: Route, stops: List<Stop>) = whenLoaded {
        drawRoute(route)
        stops.forEachIndexed { index, stop -> markers += marker(index + 1, stop) }
        labelMarkers()
    }

    /** Shows the break [stops] as markers of another colour in place of the last ones; an empty list removes them. */
    fun showPause(stops: List<Stop>) {
        pauseMarkers.forEach { it.remove() }
        pauseMarkers.clear()
        stops.forEachIndexed { index, stop -> pauseMarkers += marker(index + 1, stop, "stop-marker pause-marker") }
        labelMarkers()
    }

    /** Sets the marker labels in [lang]. */
    fun render(lang: Lang) {
        this.lang = lang
        labelMarkers()
    }

    /** Marks the markers of [stop] with aria-current and clears the mark from all others; null clears all. */
    fun select(stop: Stop?) {
        selectedId = stop?.place?.osmId
        val elements = document.querySelectorAll(".stop-marker")
        for (i in 0 until elements.length) {
            val element = elements.item(i) as Element
            if (selectedId != null && element.getAttribute("data-osm-id") == selectedId) {
                element.setAttribute("aria-current", "true")
            } else {
                element.removeAttribute("aria-current")
            }
        }
    }

    private fun whenLoaded(change: () -> Unit) {
        if (loaded) {
            change()
        } else {
            waiting += change
        }
    }

    /** Sets [route] as the muted line and fits the view to it; the stops, the break stops and the progress line are removed. */
    private fun drawRoute(route: Route) {
        plannedRoute = route
        setLine(ROUTE_LAYER, route.points)
        setLine(PROGRESS_LAYER, emptyList())
        markers.forEach { it.remove() }
        markers.clear()
        pauseMarkers.forEach { it.remove() }
        pauseMarkers.clear()
        val bounds = arrayOf(
            arrayOf(route.points.minOf { it.lon }, route.points.minOf { it.lat }),
            arrayOf(route.points.maxOf { it.lon }, route.points.maxOf { it.lat }),
        )
        map.fitBounds(bounds, js("({padding: 40})"))
    }

    /** The two lines, each a source and a layer, added in [routeLayerOrder] so the progress line is drawn over the route. */
    private fun addLines() {
        for (id in routeLayerOrder()) {
            val sourceOptions: dynamic = js("({type: 'geojson'})")
            sourceOptions.data = lineData(emptyList())
            map.addSource(id, sourceOptions)
            val layer: dynamic = js("({type: 'line', paint: {'line-width': 4}})")
            layer.id = id
            layer.source = id
            layer.paint["line-color"] = if (id == ROUTE_LAYER) MUTED_LINE else ACCENT_LINE
            map.addLayer(layer)
        }
    }

    private fun setLine(id: String, points: List<RoutePoint>) {
        map.getSource(id).setData(lineData(points))
    }

    /** The GeoJSON of [points] as a line; fewer than two points give an empty collection, which draws nothing. */
    private fun lineData(points: List<RoutePoint>): dynamic {
        if (points.size < 2) return js("({type: 'FeatureCollection', features: []})")
        val coordinates = points.map { arrayOf(it.lon, it.lat) }.toTypedArray()
        val geometry: dynamic = js("({type: 'LineString'})")
        geometry.coordinates = coordinates
        val feature: dynamic = js("({type: 'Feature', properties: {}})")
        feature.geometry = geometry
        return feature
    }

    /** A marker whose element is a button; its tap opens the stop's card. */
    private fun marker(number: Int, stop: Stop, className: String = "stop-marker"): Marker {
        val button = document.createElement("button") as HTMLButtonElement
        button.type = "button"
        button.className = className
        button.setAttribute("data-osm-id", stop.place.osmId)
        if (stop.place.osmId == selectedId) button.setAttribute("aria-current", "true")
        button.textContent = number.toString()
        button.addEventListener("click", { onStop(stop) })
        val options: dynamic = js("({})")
        options.element = button
        return Marker(options).setLngLat(arrayOf(stop.place.lon, stop.place.lat)).addTo(map)
    }

    private fun labelMarkers() {
        markers.forEachIndexed { index, marker ->
            marker.getElement().setAttribute("aria-label", Messages.text(lang, "map.stop", mapOf("number" to index + 1)))
        }
        pauseMarkers.forEachIndexed { index, marker ->
            marker.getElement().setAttribute("aria-label", Messages.text(lang, "map.pause", mapOf("number" to index + 1)))
        }
    }
}
