package trip.web

import kotlinx.browser.document
import kotlinx.browser.localStorage
import kotlinx.browser.window
import org.w3c.dom.HTMLElement
import trip.i18n.Lang
import trip.i18n.Messages
import trip.net.SavedDemoLoader
import trip.start.demoRequested

// The start screen and the language switch, with the map under them: the route and its stops, then the stop card and the trip.

private var lang: Lang = Lang.En

private fun storedLang(): Lang? =
    try { localStorage.getItem("lang")?.let { tag -> Lang.entries.firstOrNull { it.tag == tag } } } catch (e: Throwable) { null }

private fun t(key: String, params: Map<String, Any> = emptyMap()) = Messages.text(lang, key, params)

private fun render(texts: HTMLElement, start: StartScreen, map: RouteMap, panel: StopPanel) {
    document.documentElement?.setAttribute("lang", lang.tag)
    document.title = t("app.name")
    texts.querySelector("#name")?.textContent = t("app.name")
    texts.querySelector("#tagline")?.textContent = t("app.tagline")
    texts.querySelector("#lang")?.textContent = t("lang.switch")
    start.render(lang)
    map.render(lang)
    panel.render(lang)
}

fun main() {
    lang = storedLang() ?: Lang.fromTag(window.navigator.language)

    val panel = StopPanel()
    val mapDiv = document.createElement("div")
    mapDiv.id = "map"
    val options: dynamic = js("({})")
    options.container = mapDiv
    options.style = "https://tiles.openfreemap.org/styles/liberty"
    options.center = arrayOf(15.0, 62.0)
    options.zoom = 4
    options.attributionControl = js("({compact: true})")
    // The bundle hides maplibre's sibling worker file, so point maplibre at the copy served beside the page.
    setWorkerUrl(window.location.href.substringBefore('#').substringBefore('?').substringBeforeLast('/') + "/maplibre-gl-worker.mjs")
    val map = RouteMap(MapLibreMap(options), panel::show)
    panel.onShown = map::select
    val loader = SavedDemoLoader(::fetchSavedText)
    val demo = if (demoRequested(window.location.search)) loader else null
    val start = StartScreen(
        onRoute = map::showRoute,
        onProgress = map::showProgress,
        onPlanned = { route, stops ->
            map.show(route, stops)
            panel.reset()
        },
        onRefiltered = { route, stops -> map.show(route, stops) },
        onPause = map::showPause,
        onStop = panel::show,
        demo = demo,
        saved = loader,
    )

    val texts = document.createElement("header") as HTMLElement
    for (id in listOf("name", "tagline")) {
        val p = document.createElement(if (id == "name") "h1" else "p")
        p.id = id
        texts.appendChild(p)
    }
    val button = document.createElement("button")
    button.id = "lang"
    button.addEventListener("click", {
        lang = if (lang == Lang.En) Lang.Sv else Lang.En
        try { localStorage.setItem("lang", lang.tag) } catch (e: Throwable) { }
        render(texts, start, map, panel)
    })
    texts.appendChild(button)
    document.body!!.appendChild(texts)
    document.body!!.appendChild(start.element)
    render(texts, start, map, panel)

    document.body!!.appendChild(mapDiv)
    document.body!!.appendChild(panel.element)
}
