package trip.start

/** True when the page's query string asks for the demo: `?demo`, `?demo=`, `?demo=1` or `?demo=true`. */
fun demoRequested(search: String): Boolean {
    for (part in search.removePrefix("?").split('&')) {
        if (part.substringBefore('=') != "demo") continue
        if (!part.contains('=')) return true
        val value = part.substringAfter('=')
        return value.isEmpty() || value == "1" || value == "true"
    }
    return false
}
