package trip.net

import trip.place.OsmElement
import trip.place.distanceMetres
import trip.plan.Route
import trip.plan.RoutePoint

/** The Overpass API's interpreter: the places host the app uses (see AGENTS.md). Requests are POSTs with `data=<query>`. */
const val OVERPASS_URL = "https://overpass-api.de/api/interpreter"

/** The server-side timeout of every query; the busy stretches of a long route need more than 60 s. */
const val OVERPASS_TIMEOUT_SECONDS = 180

/**
 * The tag filters for what gives a category in OsmPlaces, plus amenity=toilets. A value is matched exactly, a null
 * value matches the key alone, and a value in [LIST_KEYS] matches as one of the `;`-separated values. `indoor=yes` is
 * not queried on its own, because it matches rooms and corridors; OsmPlaces still reads it on places found by other tags.
 * `playground=*` finds the equipment nodes inside playgrounds.
 */
private val TAGS: List<Pair<String, String?>> = listOf(
    "leisure" to "playground",
    "playground" to null,
    "tourism" to "zoo",
    "zoo" to null,
    "tourism" to "aquarium",
    "amenity" to "restaurant",
    "amenity" to "fast_food",
    "amenity" to "cafe",
    "amenity" to "ice_cream",
    "cuisine" to "ice_cream",
    "leisure" to "swimming_pool",
    "leisure" to "water_park",
    "leisure" to "beach_resort",
    "natural" to "beach",
    "leisure" to "nature_reserve",
    "leisure" to "park",
    "tourism" to "museum",
    "leisure" to "indoor_play",
    "highway" to "rest_area",
    "highway" to "services",
    "tourism" to "picnic_site",
    "amenity" to "toilets",
)

/** The keys OsmPlaces splits on `;`, so that `cuisine=pizza;ice_cream` counts as ice_cream. */
private val LIST_KEYS = setOf("cuisine")

/**
 * The route's points at least [everyMetres] apart: the first point, each point at least [everyMetres] from the last
 * kept one, and always the last point.
 */
fun simplify(route: Route, everyMetres: Double = 5000.0): List<RoutePoint> {
    val points = route.points
    val kept = mutableListOf(points.first())
    for (point in points.subList(1, points.lastIndex)) {
        val last = kept.last()
        if (distanceMetres(last.lat, last.lon, point.lat, point.lon) >= everyMetres) kept += point
    }
    kept += points.last()
    return kept
}

/**
 * An Overpass QL query for the places of the categories and toilets within [radiusMetres] of the simplified route.
 * Each tag is one `nwr(around:...)` filter over all the points; the result comes with centres and tags.
 */
fun query(route: Route, radiusMetres: Int = 2000): String {
    val around = simplify(route).joinToString(",", prefix = "around:$radiusMetres,") {
        "${coordinate(it.lat)},${coordinate(it.lon)}"
    }
    val filters = TAGS.joinToString("\n") { (key, value) ->
        val tag = when {
            value == null -> "[\"$key\"]"
            key in LIST_KEYS -> "[\"$key\"~\"(^|;)$value(;|$)\"]"
            else -> "[\"$key\"=\"$value\"]"
        }
        "  nwr($around)$tag;"
    }
    return "[out:json][timeout:$OVERPASS_TIMEOUT_SECONDS];\n(\n$filters\n);\nout center tags;"
}

/**
 * The element for an Overpass result: a node at its own position, a way or relation at its centre. Null when the
 * position is missing.
 */
fun elementFrom(
    type: String,
    id: Long,
    lat: Double?,
    lon: Double?,
    centerLat: Double?,
    centerLon: Double?,
    tags: Map<String, String>,
): OsmElement? {
    val (latitude, longitude) = if (type == "node") lat to lon else centerLat to centerLon
    if (latitude == null || longitude == null) return null
    return OsmElement(type, id, latitude, longitude, tags)
}
