package trip.net

/** The places of a live Nominatim answer given as JSON [text]; any failure throws IllegalArgumentException with the message key `error.search`. */
fun liveFounds(text: String): List<Found> =
    try {
        val places = parseJson(text) as? List<*> ?: throw IllegalArgumentException("A search answer is a list")
        places.mapNotNull { place -> foundOf(place) }
    } catch (e: IllegalArgumentException) {
        throw IllegalArgumentException("error.search", e)
    }

/** The place of one element of a search answer, or null when the element is not a place. */
private fun foundOf(place: Any?): Found? {
    val element = place as? Map<*, *> ?: return null
    val displayName = element["display_name"] as? String ?: return null
    val lat = element["lat"] as? String ?: return null
    val lon = element["lon"] as? String ?: return null
    return found(displayName, lat, lon)
}
