package trip.net

/**
 * How long to wait before retrying after [failedAttempts] failures of one request, or null to give up. The first failure
 * waits 2 seconds, the second 5 seconds, and after the third failure the request is not retried again.
 */
fun retryDelayMs(failedAttempts: Int): Long? {
    require(failedAttempts >= 1) { "failedAttempts must be at least 1, was $failedAttempts" }
    return when (failedAttempts) {
        1 -> 2000L
        2 -> 5000L
        else -> null
    }
}
