package trip.place

import trip.i18n.Lang
import trip.i18n.Messages

/** The name of [name] when it has one; otherwise "Unnamed place" with the first kind in [Category] order, such as "Unnamed place (Play)". */
fun placeLabel(name: String?, categories: Set<Category>, lang: Lang): String {
    if (!name.isNullOrBlank()) return name
    val category = Category.entries.firstOrNull { it in categories }
        ?: return Messages.text(lang, "stop.unnamed")
    return Messages.text(lang, "stop.unnamed.kind", mapOf("kind" to Messages.text(lang, "category.${category.name}")))
}
