package trip.net

import trip.plan.Route

/** True when the saved answer may stand in for a failed live query: only for the demo route, never while the live query works, and the screen must say saved data is in use (see savedNotice). */
fun useSavedPlaces(route: Route, liveFailed: Boolean, savedAvailable: Boolean): Boolean =
    liveFailed && savedAvailable && fitsSavedDemoRoute(route)
