package trip

/** An age span in whole months, both ends inclusive: an exact age, an age group, or a custom range. */
data class AgeSpan(val fromMonths: Int, val toMonths: Int) {
    init {
        require(fromMonths >= 0 && fromMonths <= toMonths) { "Age span must be 0 or more and from <= to, was $fromMonths-$toMonths" }
    }

    fun contains(months: Int): Boolean = months in fromMonths..toMonths

    fun overlaps(other: AgeSpan): Boolean = fromMonths <= other.toMonths && other.fromMonths <= toMonths

    companion object {
        fun of(group: AgeGroup): AgeSpan = AgeSpan(group.minMonths, group.maxMonthsExclusive - 1)
    }
}

/** One child: an exact age in months, or an age span when only a range is known. */
sealed interface Child {
    /** The months this child may be in. */
    fun span(): AgeSpan

    data class Exact(val ageMonths: Int) : Child {
        init {
            require(ageMonths >= 0) { "Age in months must be 0 or more, was $ageMonths" }
        }

        override fun span(): AgeSpan = AgeSpan(ageMonths, ageMonths)
    }

    data class InSpan(val span: AgeSpan) : Child {
        override fun span(): AgeSpan = span
    }
}

enum class Interest { Animals, Dinosaurs, Trains, Sport, Swimming, Nature, Adventure, History, Science }

enum class Need { Toilet, ChangingTable, Pram, Food, Coffee, Charging, Free, Indoor }

/** A family and what it needs from a stop; every place is scored against it (Family Match). */
data class Family(
    val children: List<Child>,
    val interests: Set<Interest> = emptySet(),
    val needs: Set<Need> = emptySet(),
    val maxDriveMinutes: Int,
) {
    init {
        require(children.isNotEmpty()) { "A family has at least one child" }
        require(maxDriveMinutes in 15..300) { "Max drive must be 15-300 minutes, was $maxDriveMinutes" }
    }

    /** From the youngest child's age to the oldest child's age. */
    fun span(): AgeSpan = AgeSpan(children.minOf { it.span().fromMonths }, children.maxOf { it.span().toMonths })

    /** The age groups that any child touches, in order. */
    fun groups(): List<AgeGroup> = AgeGroup.entries.filter { group ->
        children.any { it.span().overlaps(AgeSpan.of(group)) }
    }
}
